  ALL.push(Q({"id":"fp-113","n":113,"fam":"systems","ch":"filtro-L04","t":"Sistema 2×2 (leer lo que piden)","topics":["filtro-sistemas"],"prompt":"Del sistema $x+2y=16$, $\\; 3x-y=-1$, el valor de $x+y$ es:","opts":["$2$","$7$","$-5$","$9$"],"ans":3,"exp":"Paso 1: resuelve el $2\\times 2$. Una vía: multiplica para cancelar. Se obtiene $x=2$, $y=7$. Paso 2: $x+y=9$. Paso 3: comprueba: $x+2y$ con $x=2$, $y=7$ da 16; $3x-y$ da -1.","fig":null,"distractores":[{"opt":"$2$","error":"Marcaste solo $x$ y no lo que pedían."},{"opt":"$7$","error":"Marcaste solo $y$."},{"opt":"$-5$","error":"Confundiste $x+y$ con $x-y$ (o al revés)."}],"d":"dificil","theory":{"lesson_id":"filtro-L04","lesson_title":"Sistema 2×2 (leer lo que piden)","concept_title":"Sistema 2×2 (leer lo que piden)","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-114","n":114,"fam":"systems","ch":"filtro-L04","t":"Sistema 2×2 (leer lo que piden)","topics":["filtro-sistemas"],"prompt":"Del sistema $2x+3y=-2$, $\\; 4x-2y=28$, el valor de $x-y$ es:","opts":["$9$","$1$","$-4$","$5$"],"ans":0,"exp":"Paso 1: resuelve el $2\\times 2$. Una vía: multiplica para cancelar. Se obtiene $x=5$, $y=-4$. Paso 2: $x-y=9$. Paso 3: comprueba: $2x+3y$ con $x=5$, $y=-4$ da -2; $4x-2y$ da 28.","fig":null,"distractores":[{"opt":"$1$","error":"Marcaste solo $x$ y no lo que pedían."},{"opt":"$-4$","error":"Marcaste solo $y$."},{"opt":"$5$","error":"Confundiste $x+y$ con $x-y$ (o al revés)."}],"d":"dificil","theory":{"lesson_id":"filtro-L04","lesson_title":"Sistema 2×2 (leer lo que piden)","concept_title":"Sistema 2×2 (leer lo que piden)","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-115","n":115,"fam":"systems","ch":"filtro-L04","t":"Sistema 2×2 (leer lo que piden)","topics":["filtro-sistemas"],"prompt":"Del sistema $3x+2y=33$, $\\; 2x-y=15$, el valor de $2x+y$ es:","opts":["$21$","$3$","$12$","$9$"],"ans":0,"exp":"Paso 1: resuelve el $2\\times 2$. Una vía: multiplica para cancelar. Se obtiene $x=9$, $y=3$. Paso 2: $2x+y=21$. Paso 3: comprueba: $3x+2y$ con $x=9$, $y=3$ da 33; $2x-y$ da 15.","fig":null,"distractores":[{"opt":"$3$","error":"Marcaste solo $x$ y no lo que pedían."},{"opt":"$12$","error":"Marcaste solo $y$."},{"opt":"$9$","error":"Confundiste $x+y$ con $x-y$ (o al revés)."}],"d":"dificil","theory":{"lesson_id":"filtro-L04","lesson_title":"Sistema 2×2 (leer lo que piden)","concept_title":"Sistema 2×2 (leer lo que piden)","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-116","n":116,"fam":"systems","ch":"filtro-L04","t":"Sistema 2×2 (leer lo que piden)","topics":["filtro-sistemas"],"prompt":"Del sistema $x+3y=16$, $\\; 3x-2y=-7$, el valor de $xy$ es:","opts":["$6$","$1$","$5$","$2$"],"ans":2,"exp":"Paso 1: resuelve el $2\\times 2$. Una vía: multiplica para cancelar. Se obtiene $x=1$, $y=5$. Paso 2: $xy=5$. Paso 3: comprueba: $x+3y$ con $x=1$, $y=5$ da 16; $3x-2y$ da -7.","fig":null,"distractores":[{"opt":"$6$","error":"Marcaste solo $x$ y no lo que pedían."},{"opt":"$1$","error":"Marcaste solo $y$."},{"opt":"$2$","error":"Confundiste $x+y$ con $x-y$ (o al revés)."}],"d":"dificil","theory":{"lesson_id":"filtro-L04","lesson_title":"Sistema 2×2 (leer lo que piden)","concept_title":"Sistema 2×2 (leer lo que piden)","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-117","n":117,"fam":"systems","ch":"filtro-L04","t":"Sistema 2×2 (leer lo que piden)","topics":["filtro-sistemas"],"prompt":"Del sistema $2x+2y=6$, $\\; 4x-y=27$, el valor de $x+y$ es:","opts":["$6$","$9$","$-3$","$3$"],"ans":3,"exp":"Paso 1: resuelve el $2\\times 2$. Una vía: multiplica para cancelar. Se obtiene $x=6$, $y=-3$. Paso 2: $x+y=3$. Paso 3: comprueba: $2x+2y$ con $x=6$, $y=-3$ da 6; $4x-y$ da 27.","fig":null,"distractores":[{"opt":"$6$","error":"Marcaste solo $x$ y no lo que pedían."},{"opt":"$9$","error":"Marcaste solo $y$."},{"opt":"$-3$","error":"Confundiste $x+y$ con $x-y$ (o al revés)."}],"d":"dificil","theory":{"lesson_id":"filtro-L04","lesson_title":"Sistema 2×2 (leer lo que piden)","concept_title":"Sistema 2×2 (leer lo que piden)","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-118","n":118,"fam":"systems","ch":"filtro-L04","t":"Sistema 2×2 (leer lo que piden)","topics":["filtro-sistemas"],"prompt":"Del sistema $3x+3y=12$, $\\; 2x-2y=-8$, el valor de $x-y$ es:","opts":["$4$","$12$","$0$","$-4$"],"ans":3,"exp":"Paso 1: resuelve el $2\\times 2$. Una vía: multiplica para cancelar. Se obtiene $x=0$, $y=4$. Paso 2: $x-y=-4$. Paso 3: comprueba: $3x+3y$ con $x=0$, $y=4$ da 12; $2x-2y$ da -8.","fig":null,"distractores":[{"opt":"$4$","error":"Marcaste solo $x$ y no lo que pedían."},{"opt":"$12$","error":"Marcaste solo $y$."},{"opt":"$0$","error":"Confundiste $x+y$ con $x-y$ (o al revés)."}],"d":"dificil","theory":{"lesson_id":"filtro-L04","lesson_title":"Sistema 2×2 (leer lo que piden)","concept_title":"Sistema 2×2 (leer lo que piden)","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-119","n":119,"fam":"systems","ch":"filtro-L04","t":"Sistema 2×2 (leer lo que piden)","topics":["filtro-sistemas"],"prompt":"Del sistema $x+2y=15$, $\\; 3x-y=3$, el valor de $2x+y$ es:","opts":["$6$","$9$","$12$","$3$"],"ans":2,"exp":"Paso 1: resuelve el $2\\times 2$. Una vía: multiplica para cancelar. Se obtiene $x=3$, $y=6$. Paso 2: $2x+y=12$. Paso 3: comprueba: $x+2y$ con $x=3$, $y=6$ da 15; $3x-y$ da 3.","fig":null,"distractores":[{"opt":"$6$","error":"Marcaste solo $x$ y no lo que pedían."},{"opt":"$9$","error":"Marcaste solo $y$."},{"opt":"$3$","error":"Confundiste $x+y$ con $x-y$ (o al revés)."}],"d":"dificil","theory":{"lesson_id":"filtro-L04","lesson_title":"Sistema 2×2 (leer lo que piden)","concept_title":"Sistema 2×2 (leer lo que piden)","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-120","n":120,"fam":"systems","ch":"filtro-L04","t":"Sistema 2×2 (leer lo que piden)","topics":["filtro-sistemas"],"prompt":"Del sistema $2x+3y=-2$, $\\; 4x-2y=-20$, el valor de $xy$ es:","opts":["$-4$","$-8$","$-2$","$2$"],"ans":1,"exp":"Paso 1: resuelve el $2\\times 2$. Una vía: multiplica para cancelar. Se obtiene $x=-4$, $y=2$. Paso 2: $xy=-8$. Paso 3: comprueba: $2x+3y$ con $x=-4$, $y=2$ da -2; $4x-2y$ da -20.","fig":null,"distractores":[{"opt":"$-4$","error":"Marcaste solo $x$ y no lo que pedían."},{"opt":"$-2$","error":"Marcaste solo $y$."},{"opt":"$2$","error":"Confundiste $x+y$ con $x-y$ (o al revés)."}],"d":"dificil","theory":{"lesson_id":"filtro-L04","lesson_title":"Sistema 2×2 (leer lo que piden)","concept_title":"Sistema 2×2 (leer lo que piden)","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-121","n":121,"fam":"factor","ch":"filtro-L03","t":"Notables y factorización","topics":["filtro-notables"],"prompt":"El desarrollo de $-x(x-2)^{2}$ es:","opts":["$-x^{3}+4x^{2}-4x$","$(-x^{2}+2x)^{2}$","$-x^{3}+2x^{2}-4x$","$-x^{3}-4x^{2}-4x$"],"ans":0,"exp":"Paso 1: abre la caja $(x-2)^{2}=x^{2}-4x+4$. Paso 2: multiplica por $-x$: $-x^{3}+4x^{2}-4x$. Paso 3: el menos de afuera pinta los tres términos. Elevar también el $-x$ es la trampa.","fig":null,"distractores":[{"opt":"$(-x^{2}+2x)^{2}$","error":"Abriste mal el notable (signo del término del medio)."},{"opt":"$-x^{3}+2x^{2}-4x$","error":"Elevaste también el factor de afuera, o te comiste un término."},{"opt":"$-x^{3}-4x^{2}-4x$","error":"Usaste otro notable (diferencia de cuadrados vs cuadrado de binomio)."}],"d":"dificil","theory":{"lesson_id":"filtro-L03","lesson_title":"Notables y factorización","concept_title":"Notables y factorización","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-122","n":122,"fam":"factor","ch":"filtro-L03","t":"Notables y factorización","topics":["filtro-notables"],"prompt":"El desarrollo de $-x(x+3)^{2}$ es:","opts":["$-x^{3}+6x^{2}-9x$","$(-x^{2}-3x)^{2}$","$-x^{3}-6x^{2}-9x$","$-x^{3}-6x^{2}+9x$"],"ans":2,"exp":"Paso 1: $(x+3)^{2}=x^{2}+6x+9$. Paso 2: $-x(x^{2}+6x+9)=-x^{3}-6x^{2}-9x$. Paso 3: un $+$ en el paréntesis no se salva del menos de afuera.","fig":null,"distractores":[{"opt":"$-x^{3}+6x^{2}-9x$","error":"Abriste mal el notable (signo del término del medio)."},{"opt":"$(-x^{2}-3x)^{2}$","error":"Elevaste también el factor de afuera, o te comiste un término."},{"opt":"$-x^{3}-6x^{2}+9x$","error":"Usaste otro notable (diferencia de cuadrados vs cuadrado de binomio)."}],"d":"dificil","theory":{"lesson_id":"filtro-L03","lesson_title":"Notables y factorización","concept_title":"Notables y factorización","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-123","n":123,"fam":"factor","ch":"filtro-L03","t":"Notables y factorización","topics":["filtro-notables"],"prompt":"El desarrollo de $2x(x-1)^{2}$ es:","opts":["$2x^{3}-4x^{2}+2x$","$2x^{3}-2x^{2}+2x$","$2x^{3}+4x^{2}+2x$","$2x^{2}(x-1)$"],"ans":0,"exp":"Paso 1: $(x-1)^{2}=x^{2}-2x+1$. Paso 2: $2x(x^{2}-2x+1)=2x^{3}-4x^{2}+2x$. Paso 3: el $2$ y la $x$ de afuera multiplican cada término.","fig":null,"distractores":[{"opt":"$2x^{3}-2x^{2}+2x$","error":"Abriste mal el notable (signo del término del medio)."},{"opt":"$2x^{3}+4x^{2}+2x$","error":"Elevaste también el factor de afuera, o te comiste un término."},{"opt":"$2x^{2}(x-1)$","error":"Usaste otro notable (diferencia de cuadrados vs cuadrado de binomio)."}],"d":"dificil","theory":{"lesson_id":"filtro-L03","lesson_title":"Notables y factorización","concept_title":"Notables y factorización","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-124","n":124,"fam":"factor","ch":"filtro-L03","t":"Notables y factorización","topics":["filtro-notables"],"prompt":"La factorización completa de $3x^{3}-12x$ es:","opts":["$3x(x-4)(x+1)$","$x(3x^{2}-12x)$","$3x(x^{2}-12)$","$3x(x-2)(x+2)$"],"ans":3,"exp":"Paso 1: factor común $3x$: $3x(x^{2}-4)$. Paso 2: diferencia de cuadrados $x^{2}-4=(x-2)(x+2)$. Paso 3: $3x(x-2)(x+2)$.","fig":null,"distractores":[{"opt":"$3x(x-4)(x+1)$","error":"Abriste mal el notable (signo del término del medio)."},{"opt":"$x(3x^{2}-12x)$","error":"Elevaste también el factor de afuera, o te comiste un término."},{"opt":"$3x(x^{2}-12)$","error":"Usaste otro notable (diferencia de cuadrados vs cuadrado de binomio)."}],"d":"dificil","theory":{"lesson_id":"filtro-L03","lesson_title":"Notables y factorización","concept_title":"Notables y factorización","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-125","n":125,"fam":"factor","ch":"filtro-L03","t":"Notables y factorización","topics":["filtro-notables"],"prompt":"$(3x-4)(3x+4)$ es igual a:","opts":["$9x^{2}+16$","$9x^{2}-12x-16$","$6x^{2}-16$","$9x^{2}-16$"],"ans":3,"exp":"Paso 1: notable $(a-b)(a+b)=a^{2}-b^{2}$ con $a=3x$, $b=4$. Paso 2: $9x^{2}-16$. Paso 3: no hay término del medio.","fig":null,"distractores":[{"opt":"$9x^{2}+16$","error":"Abriste mal el notable (signo del término del medio)."},{"opt":"$9x^{2}-12x-16$","error":"Elevaste también el factor de afuera, o te comiste un término."},{"opt":"$6x^{2}-16$","error":"Usaste otro notable (diferencia de cuadrados vs cuadrado de binomio)."}],"d":"dificil","theory":{"lesson_id":"filtro-L03","lesson_title":"Notables y factorización","concept_title":"Notables y factorización","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-126","n":126,"fam":"factor","ch":"filtro-L03","t":"Notables y factorización","topics":["filtro-notables"],"prompt":"$(2x+5)^{2}$ es igual a:","opts":["$4x^{2}+20x+25$","$4x^{2}+20x-25$","$4x^{2}+10x+25$","$4x^{2}+25$"],"ans":0,"exp":"Paso 1: $(a+b)^{2}=a^{2}+2ab+b^{2}$. Paso 2: $4x^{2}+2\\cdot 2x\\cdot 5+25=4x^{2}+20x+25$. Paso 3: el término del medio es el doble del producto, no $10x$.","fig":null,"distractores":[{"opt":"$4x^{2}+20x-25$","error":"Abriste mal el notable (signo del término del medio)."},{"opt":"$4x^{2}+10x+25$","error":"Elevaste también el factor de afuera, o te comiste un término."},{"opt":"$4x^{2}+25$","error":"Usaste otro notable (diferencia de cuadrados vs cuadrado de binomio)."}],"d":"dificil","theory":{"lesson_id":"filtro-L03","lesson_title":"Notables y factorización","concept_title":"Notables y factorización","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-127","n":127,"fam":"factor","ch":"filtro-L03","t":"Notables y factorización","topics":["filtro-notables"],"prompt":"La factorización de $x^{3}-8$ es:","opts":["$(x-8)(x^{2}+1)$","$(x-2)(x^{2}+2x+4)$","$(x-2)^{3}$","$(x-2)(x^{2}-2x+4)$"],"ans":1,"exp":"Paso 1: diferencia de cubos $a^{3}-b^{3}=(a-b)(a^{2}+ab+b^{2})$ con $a=x$, $b=2$. Paso 2: $(x-2)(x^{2}+2x+4)$. Paso 3: el medio del trinomio es $+ab$, no $-ab$.","fig":null,"distractores":[{"opt":"$(x-8)(x^{2}+1)$","error":"Abriste mal el notable (signo del término del medio)."},{"opt":"$(x-2)^{3}$","error":"Elevaste también el factor de afuera, o te comiste un término."},{"opt":"$(x-2)(x^{2}-2x+4)$","error":"Usaste otro notable (diferencia de cuadrados vs cuadrado de binomio)."}],"d":"dificil","theory":{"lesson_id":"filtro-L03","lesson_title":"Notables y factorización","concept_title":"Notables y factorización","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-128","n":128,"fam":"factor","ch":"filtro-L03","t":"Notables y factorización","topics":["filtro-notables"],"prompt":"Factor común completo de $4x^{3}y-8x^{2}y^{2}$:","opts":["$4x^{2}(y-2y^{2})$","$4xy(x^{2}-2xy)$","$4x^{2}y(x-2y)$","$4x^{2}y(x-2xy)$"],"ans":2,"exp":"Paso 1: el común es $4x^{2}y$. Paso 2: $4x^{2}y\\cdot x=4x^{3}y$ y $4x^{2}y\\cdot(-2y)=-8x^{2}y^{2}$. Paso 3: queda $4x^{2}y(x-2y)$.","fig":null,"distractores":[{"opt":"$4x^{2}(y-2y^{2})$","error":"Abriste mal el notable (signo del término del medio)."},{"opt":"$4xy(x^{2}-2xy)$","error":"Elevaste también el factor de afuera, o te comiste un término."},{"opt":"$4x^{2}y(x-2xy)$","error":"Usaste otro notable (diferencia de cuadrados vs cuadrado de binomio)."}],"d":"dificil","theory":{"lesson_id":"filtro-L03","lesson_title":"Notables y factorización","concept_title":"Notables y factorización","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-129","n":129,"fam":"factor","ch":"filtro-L03","t":"Notables y factorización","topics":["filtro-notables"],"prompt":"$-2x(x+1)^{2}$ desarrollado es:","opts":["$-2x^{3}+4x^{2}-2x$","$2x^{3}+4x^{2}+2x$","$-2x^{3}-2x^{2}-2x$","$-2x^{3}-4x^{2}-2x$"],"ans":3,"exp":"Paso 1: $(x+1)^{2}=x^{2}+2x+1$. Paso 2: $-2x(x^{2}+2x+1)=-2x^{3}-4x^{2}-2x$. Paso 3: el $-2$ pinta todo.","fig":null,"distractores":[{"opt":"$-2x^{3}+4x^{2}-2x$","error":"Abriste mal el notable (signo del término del medio)."},{"opt":"$2x^{3}+4x^{2}+2x$","error":"Elevaste también el factor de afuera, o te comiste un término."},{"opt":"$-2x^{3}-2x^{2}-2x$","error":"Usaste otro notable (diferencia de cuadrados vs cuadrado de binomio)."}],"d":"dificil","theory":{"lesson_id":"filtro-L03","lesson_title":"Notables y factorización","concept_title":"Notables y factorización","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-130","n":130,"fam":"factor","ch":"filtro-L03","t":"Notables y factorización","topics":["filtro-notables"],"prompt":"$x^{2}-10x+25$ factoriza como:","opts":["$(x-5)^{2}$","$(x+5)^{2}$","$(x-5)(x+5)$","$(x-25)(x+1)$"],"ans":0,"exp":"Paso 1: es cuadrado perfecto $a^{2}-2ab+b^{2}$ con $a=x$, $b=5$. Paso 2: $(x-5)^{2}$. Paso 3: $(x+5)^{2}$ tendría $+10x$. $(x-5)(x+5)$ es diferencia de cuadrados, sin término del medio.","fig":null,"distractores":[{"opt":"$(x+5)^{2}$","error":"Abriste mal el notable (signo del término del medio)."},{"opt":"$(x-5)(x+5)$","error":"Elevaste también el factor de afuera, o te comiste un término."},{"opt":"$(x-25)(x+1)$","error":"Usaste otro notable (diferencia de cuadrados vs cuadrado de binomio)."}],"d":"dificil","theory":{"lesson_id":"filtro-L03","lesson_title":"Notables y factorización","concept_title":"Notables y factorización","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-131","n":131,"fam":"ineq","ch":"filtro-L05","t":"Inecuaciones y valor absoluto","topics":["filtro-ineq"],"prompt":"Si $x<0$, la expresión $-x(x-2)$ es:","opts":["cero","a veces positiva y a veces negativa","siempre negativa","siempre positiva"],"ans":2,"exp":"Paso 1: $x<0$ ⇒ $-x>0$. Paso 2: $x-2< -2<0$. Paso 3: $(+)\\cdot(-)$ es negativo. Nunca es cero porque $x=0$ y $x=2$ están fuera de $x<0$.","fig":null,"distractores":[{"opt":"cero","error":"No volteaste al dividir por un negativo, o invertiste el intervalo."},{"opt":"a veces positiva y a veces negativa","error":"Confundiste las dos puertas del valor absoluto con una sola."},{"opt":"siempre positiva","error":"Incluiste un cero o un hoyo que la desigualdad no admite."}],"d":"dificil","theory":{"lesson_id":"filtro-L05","lesson_title":"Inecuaciones y valor absoluto","concept_title":"Inecuaciones y valor absoluto","anchor":"h-la-regla-solo-esto"}}));
