  ALL.push(Q({"id":"fp-133","n":133,"fam":"ineq","ch":"filtro-L05","t":"Inecuaciones y valor absoluto","topics":["filtro-ineq"],"prompt":"Si $0<x<2$, la expresión $-x(x-2)$ es:","opts":["siempre positiva","cero","siempre negativa","no se puede saber"],"ans":0,"exp":"Paso 1: $x>0$ ⇒ $-x<0$. Paso 2: $x-2<0$. Paso 3: $(- )\\cdot(-)$ es positivo. Los ceros $x=0$ y $x=2$ no entran en el abierto.","fig":null,"distractores":[{"opt":"cero","error":"No volteaste al dividir por un negativo, o invertiste el intervalo."},{"opt":"siempre negativa","error":"Confundiste las dos puertas del valor absoluto con una sola."},{"opt":"no se puede saber","error":"Incluiste un cero o un hoyo que la desigualdad no admite."}],"d":"dificil","theory":{"lesson_id":"filtro-L05","lesson_title":"Inecuaciones y valor absoluto","concept_title":"Inecuaciones y valor absoluto","anchor":"h-la-regla-solo-esto"}}));
