  ALL.push(Q({"id":"fp-135","n":135,"fam":"ineq","ch":"filtro-L05","t":"Inecuaciones y valor absoluto","topics":["filtro-ineq"],"prompt":"La inecuación $-4x+1<9$ equivale a:","opts":["$x< -2$","$x> -2$","$x<2$","$x>2$"],"ans":1,"exp":"Paso 1: $-4x<8$. Paso 2: divide por $-4$ y voltea: $x> -2$. Paso 3: el $1$ se resta primero, no se divide.","fig":null,"distractores":[{"opt":"$x< -2$","error":"No volteaste al dividir por un negativo, o invertiste el intervalo."},{"opt":"$x<2$","error":"Confundiste las dos puertas del valor absoluto con una sola."},{"opt":"$x>2$","error":"Incluiste un cero o un hoyo que la desigualdad no admite."}],"d":"dificil","theory":{"lesson_id":"filtro-L05","lesson_title":"Inecuaciones y valor absoluto","concept_title":"Inecuaciones y valor absoluto","anchor":"h-la-regla-solo-esto"}}));
