  ALL.push(Q({"id":"fp-137","n":137,"fam":"ineq","ch":"filtro-L05","t":"Inecuaciones y valor absoluto","topics":["filtro-ineq"],"prompt":"$|2x+1|<5$ equivale a:","opts":["$x>-3$","$x<2$","$-3<x<2$","$x<-3$ o $x>2$"],"ans":2,"exp":"Paso 1: $-5<2x+1<5$. Paso 2: $-6<2x<4$. Paso 3: $-3<x<2$. La unión $x<-3$ o $x>2$ sería para $|\\,|>5$.","fig":null,"distractores":[{"opt":"$x>-3$","error":"No volteaste al dividir por un negativo, o invertiste el intervalo."},{"opt":"$x<2$","error":"Confundiste las dos puertas del valor absoluto con una sola."},{"opt":"$x<-3$ o $x>2$","error":"Incluiste un cero o un hoyo que la desigualdad no admite."}],"d":"dificil","theory":{"lesson_id":"filtro-L05","lesson_title":"Inecuaciones y valor absoluto","concept_title":"Inecuaciones y valor absoluto","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-138","n":138,"fam":"ineq","ch":"filtro-L05","t":"Inecuaciones y valor absoluto","topics":["filtro-ineq"],"prompt":"$|x+4|\\ge 2$ equivale a:","opts":["$x\\le -6$ o $x\\ge -2$","$-6\\le x\\le -2$","$x\\ge -2$","$x\\le 2$"],"ans":0,"exp":"Paso 1: $|A|\\ge k$ es afuera: $A\\le -k$ o $A\\ge k$. Paso 2: $x+4\\le -2$ o $x+4\\ge 2$. Paso 3: $x\\le -6$ o $x\\ge -2$. El intervalo cerrado del medio es la desigualdad contraria.","fig":null,"distractores":[{"opt":"$-6\\le x\\le -2$","error":"No volteaste al dividir por un negativo, o invertiste el intervalo."},{"opt":"$x\\ge -2$","error":"Confundiste las dos puertas del valor absoluto con una sola."},{"opt":"$x\\le 2$","error":"Incluiste un cero o un hoyo que la desigualdad no admite."}],"d":"dificil","theory":{"lesson_id":"filtro-L05","lesson_title":"Inecuaciones y valor absoluto","concept_title":"Inecuaciones y valor absoluto","anchor":"h-la-regla-solo-esto"}}));
