  ALL.push(Q({"id":"fp-140","n":140,"fam":"ineq","ch":"filtro-L05","t":"Inecuaciones y valor absoluto","topics":["filtro-ineq"],"prompt":"Si $x>4$, el signo de $-x(x+1)(x-4)$ es:","opts":["positivo","depende de $x$","negativo","cero"],"ans":2,"exp":"Paso 1: $x>4$ ⇒ $-x<0$, $x+1>0$, $x-4>0$. Paso 2: $(- )\\cdot(+)\\cdot(+)$ es negativo. Paso 3: tres factores, cuenta los menos.","fig":null,"distractores":[{"opt":"positivo","error":"No volteaste al dividir por un negativo, o invertiste el intervalo."},{"opt":"depende de $x$","error":"Confundiste las dos puertas del valor absoluto con una sola."},{"opt":"cero","error":"Incluiste un cero o un hoyo que la desigualdad no admite."}],"d":"dificil","theory":{"lesson_id":"filtro-L05","lesson_title":"Inecuaciones y valor absoluto","concept_title":"Inecuaciones y valor absoluto","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-141","n":141,"fam":"ineq","ch":"filtro-L05","t":"Inecuaciones y valor absoluto","topics":["filtro-ineq"],"prompt":"$3x-2>5x+6$ equivale a:","opts":["$x> -4$","$x>4$","$x<4$","$x< -4$"],"ans":3,"exp":"Paso 1: $3x-5x>6+2$ ⇒ $-2x>8$. Paso 2: voltea: $x< -4$. Paso 3: pasar $5x$ cambia el signo de ese término, no de toda la desigualdad todavía.","fig":null,"distractores":[{"opt":"$x> -4$","error":"No volteaste al dividir por un negativo, o invertiste el intervalo."},{"opt":"$x>4$","error":"Confundiste las dos puertas del valor absoluto con una sola."},{"opt":"$x<4$","error":"Incluiste un cero o un hoyo que la desigualdad no admite."}],"d":"dificil","theory":{"lesson_id":"filtro-L05","lesson_title":"Inecuaciones y valor absoluto","concept_title":"Inecuaciones y valor absoluto","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-142","n":142,"fam":"ineq","ch":"filtro-L05","t":"Inecuaciones y valor absoluto","topics":["filtro-ineq"],"prompt":"$|x|=0$ tiene:","opts":["dos soluciones","infinitas","ninguna","una solución"],"ans":3,"exp":"Paso 1: distancia a $0$ igual a $0$. Paso 2: solo $x=0$. Paso 3: las dos puertas caen en el mismo punto.","fig":null,"distractores":[{"opt":"dos soluciones","error":"No volteaste al dividir por un negativo, o invertiste el intervalo."},{"opt":"infinitas","error":"Confundiste las dos puertas del valor absoluto con una sola."},{"opt":"ninguna","error":"Incluiste un cero o un hoyo que la desigualdad no admite."}],"d":"dificil","theory":{"lesson_id":"filtro-L05","lesson_title":"Inecuaciones y valor absoluto","concept_title":"Inecuaciones y valor absoluto","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-143","n":143,"fam":"ineq","ch":"filtro-L05","t":"Inecuaciones y valor absoluto","topics":["filtro-ineq"],"prompt":"La solución de $|x+1|=|x-5|$ es:","opts":["$x=3$","$x=-1$ y $x=5$","ninguna","$x=2$"],"ans":3,"exp":"Paso 1: equidistante de $-1$ y de $5$. Paso 2: el punto medio es $x=2$. Paso 3: no son los ceros de cada valor absoluto.","fig":null,"distractores":[{"opt":"$x=3$","error":"No volteaste al dividir por un negativo, o invertiste el intervalo."},{"opt":"$x=-1$ y $x=5$","error":"Confundiste las dos puertas del valor absoluto con una sola."},{"opt":"ninguna","error":"Incluiste un cero o un hoyo que la desigualdad no admite."}],"d":"dificil","theory":{"lesson_id":"filtro-L05","lesson_title":"Inecuaciones y valor absoluto","concept_title":"Inecuaciones y valor absoluto","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-144","n":144,"fam":"ineq","ch":"filtro-L05","t":"Inecuaciones y valor absoluto","topics":["filtro-ineq"],"prompt":"Si $x<0$, $-x^{2}$ es:","opts":["positivo, porque hay un menos y $x$ es negativo","siempre negativo (salvo $x=0$, que no entra)","positivo si $|x|>1$","cero"],"ans":1,"exp":"Paso 1: $x^{2}$ siempre $\\ge 0$. Paso 2: el menos de afuera lo pinta: $-x^{2}\\le 0$. Paso 3: con $x\\neq 0$ es estrictamente negativo. El imán: $-x^{2}=-(x^{2})$, no $(-x)^{2}$.","fig":null,"distractores":[{"opt":"positivo, porque hay un menos y $x$ es negativo","error":"No volteaste al dividir por un negativo, o invertiste el intervalo."},{"opt":"positivo si $|x|>1$","error":"Confundiste las dos puertas del valor absoluto con una sola."},{"opt":"cero","error":"Incluiste un cero o un hoyo que la desigualdad no admite."}],"d":"dificil","theory":{"lesson_id":"filtro-L05","lesson_title":"Inecuaciones y valor absoluto","concept_title":"Inecuaciones y valor absoluto","anchor":"h-la-regla-solo-esto"}}));
