  ALL.push(Q({"id":"fp-149","n":149,"fam":"ineq","ch":"filtro-L05","t":"Inecuaciones y valor absoluto","topics":["filtro-ineq"],"prompt":"Si $x>0$, $\\dfrac{-x}{x+2}$ es:","opts":["positivo si $x>2$","siempre positivo","siempre negativo","cero"],"ans":2,"exp":"Paso 1: numerador $-x<0$. Paso 2: denominador $x+2>2>0$. Paso 3: negativo sobre positivo es negativo.","fig":null,"distractores":[{"opt":"positivo si $x>2$","error":"No volteaste al dividir por un negativo, o invertiste el intervalo."},{"opt":"siempre positivo","error":"Confundiste las dos puertas del valor absoluto con una sola."},{"opt":"cero","error":"Incluiste un cero o un hoyo que la desigualdad no admite."}],"d":"dificil","theory":{"lesson_id":"filtro-L05","lesson_title":"Inecuaciones y valor absoluto","concept_title":"Inecuaciones y valor absoluto","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-150","n":150,"fam":"ineq","ch":"filtro-L05","t":"Inecuaciones y valor absoluto","topics":["filtro-ineq"],"prompt":"$|3-x|=4$ tiene soluciones:","opts":["$x=1$ y $x=-7$","$x=-1$ y $x=7$","$x=4$ y $x=-4$","solo $x=7$"],"ans":1,"exp":"Paso 1: $3-x=4$ o $3-x=-4$. Paso 2: $-x=1\\Rightarrow x=-1$; $-x=-7\\Rightarrow x=7$. Paso 3: $|3-x|=|x-3|$, mismas puertas que $|x-3|=4$.","fig":null,"distractores":[{"opt":"$x=1$ y $x=-7$","error":"No volteaste al dividir por un negativo, o invertiste el intervalo."},{"opt":"$x=4$ y $x=-4$","error":"Confundiste las dos puertas del valor absoluto con una sola."},{"opt":"solo $x=7$","error":"Incluiste un cero o un hoyo que la desigualdad no admite."}],"d":"dificil","theory":{"lesson_id":"filtro-L05","lesson_title":"Inecuaciones y valor absoluto","concept_title":"Inecuaciones y valor absoluto","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-151","n":151,"fam":"domain","ch":"filtro-L02","t":"Dominio y hoyos","topics":["filtro-dominio"],"prompt":"$\\dfrac{x^{2}+1}{x^{2}-9}$ no está definida cuando:","opts":["$x=3$ o $x=-3$","$x=0$","$x=9$","$x=1$"],"ans":0,"exp":"Paso 1: el piso $x^{2}-9=0$. Paso 2: $x=\\pm 3$. Paso 3: el $+1$ de arriba no tapa el hoyo. $x=9$ es leer el $9$ como si fuera la raíz.","fig":null,"distractores":[{"opt":"$x=0$","error":"Leíste el número que se ve (el $9$, el $4$) como si fuera la raíz."},{"opt":"$x=9$","error":"Cancelaste un factor y borraste el hoyo del dominio original."},{"opt":"$x=1$","error":"Confundiste un cero del numerador con un hoyo."}],"d":"dificil","theory":{"lesson_id":"filtro-L02","lesson_title":"Dominio y hoyos","concept_title":"Dominio y hoyos","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-152","n":152,"fam":"domain","ch":"filtro-L02","t":"Dominio y hoyos","topics":["filtro-dominio"],"prompt":"$\\dfrac{x+2}{x^{2}-x-6}$ se rompe en:","opts":["solo $x=3$","solo $x=-2$","$x=6$","$x=3$ y $x=-2$"],"ans":3,"exp":"Paso 1: $x^{2}-x-6=(x-3)(x+2)=0$. Paso 2: hoyos en $x=3$ y $x=-2$. Paso 3: aunque $x+2$ se cancele, el dominio original sigue sin $x=-2$.","fig":null,"distractores":[{"opt":"solo $x=3$","error":"Leíste el número que se ve (el $9$, el $4$) como si fuera la raíz."},{"opt":"solo $x=-2$","error":"Cancelaste un factor y borraste el hoyo del dominio original."},{"opt":"$x=6$","error":"Confundiste un cero del numerador con un hoyo."}],"d":"dificil","theory":{"lesson_id":"filtro-L02","lesson_title":"Dominio y hoyos","concept_title":"Dominio y hoyos","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-153","n":153,"fam":"domain","ch":"filtro-L02","t":"Dominio y hoyos","topics":["filtro-dominio"],"prompt":"$\\sqrt{2x-8}$ está definida en $\\mathbb{R}$ si:","opts":["$x\\ge 4$","$x\\ge 8$","$x\\ge 2$","$x>0$"],"ans":0,"exp":"Paso 1: adentro $\\ge 0$: $2x-8\\ge 0$. Paso 2: $x\\ge 4$. Paso 3: no pidas $x\\ge 8$ (eso sería $\\sqrt{x-8}$).","fig":null,"distractores":[{"opt":"$x\\ge 8$","error":"Leíste el número que se ve (el $9$, el $4$) como si fuera la raíz."},{"opt":"$x\\ge 2$","error":"Cancelaste un factor y borraste el hoyo del dominio original."},{"opt":"$x>0$","error":"Confundiste un cero del numerador con un hoyo."}],"d":"dificil","theory":{"lesson_id":"filtro-L02","lesson_title":"Dominio y hoyos","concept_title":"Dominio y hoyos","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-154","n":154,"fam":"domain","ch":"filtro-L02","t":"Dominio y hoyos","topics":["filtro-dominio"],"prompt":"$\\dfrac{1}{\\operatorname{sen} x}$ no existe cuando:","opts":["nunca se rompe","$x=0^{\\circ}+180^{\\circ}k$","$x=90^{\\circ}$","$x=45^{\\circ}$"],"ans":1,"exp":"Paso 1: $\\operatorname{sen} x=0$. Paso 2: en $0^{\\circ}$, $180^{\\circ}$, $360^{\\circ}$,… Paso 3: en $90^{\\circ}$ el seno es $1$, ahí sí existe y vale $1$.","fig":null,"distractores":[{"opt":"nunca se rompe","error":"Leíste el número que se ve (el $9$, el $4$) como si fuera la raíz."},{"opt":"$x=90^{\\circ}$","error":"Cancelaste un factor y borraste el hoyo del dominio original."},{"opt":"$x=45^{\\circ}$","error":"Confundiste un cero del numerador con un hoyo."}],"d":"dificil","theory":{"lesson_id":"filtro-L02","lesson_title":"Dominio y hoyos","concept_title":"Dominio y hoyos","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-155","n":155,"fam":"domain","ch":"filtro-L02","t":"Dominio y hoyos","topics":["filtro-dominio"],"prompt":"$\\tan x$ no existe en:","opts":["$45^{\\circ}$","$0^{\\circ}$","$90^{\\circ}$ (y $90^{\\circ}+180^{\\circ}k$)","$180^{\\circ}$"],"ans":2,"exp":"Paso 1: $\\tan=\\dfrac{\\operatorname{sen}}{\\cos}$, se rompe si $\\cos=0$. Paso 2: $\\cos 90^{\\circ}=0$. Paso 3: en $180^{\\circ}$ el coseno es $-1$, la tangente vale $0$.","fig":null,"distractores":[{"opt":"$45^{\\circ}$","error":"Leíste el número que se ve (el $9$, el $4$) como si fuera la raíz."},{"opt":"$0^{\\circ}$","error":"Cancelaste un factor y borraste el hoyo del dominio original."},{"opt":"$180^{\\circ}$","error":"Confundiste un cero del numerador con un hoyo."}],"d":"dificil","theory":{"lesson_id":"filtro-L02","lesson_title":"Dominio y hoyos","concept_title":"Dominio y hoyos","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-156","n":156,"fam":"domain","ch":"filtro-L02","t":"Dominio y hoyos","topics":["filtro-dominio"],"prompt":"El dominio de $\\dfrac{x}{x^{2}+4}$ es:","opts":["$x\\neq 2$","todos los reales","$x\\neq 0$","$x\\neq \\pm 2$"],"ans":1,"exp":"Paso 1: $x^{2}+4=0$ ⇒ $x^{2}=-4$, imposible en $\\mathbb{R}$. Paso 2: no hay hoyo. Paso 3: $x=0$ anula el numerador, no el piso: la función vale $0$, existe.","fig":null,"distractores":[{"opt":"$x\\neq 2$","error":"Leíste el número que se ve (el $9$, el $4$) como si fuera la raíz."},{"opt":"$x\\neq 0$","error":"Cancelaste un factor y borraste el hoyo del dominio original."},{"opt":"$x\\neq \\pm 2$","error":"Confundiste un cero del numerador con un hoyo."}],"d":"dificil","theory":{"lesson_id":"filtro-L02","lesson_title":"Dominio y hoyos","concept_title":"Dominio y hoyos","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-157","n":157,"fam":"domain","ch":"filtro-L02","t":"Dominio y hoyos","topics":["filtro-dominio"],"prompt":"$\\dfrac{3}{(x-1)(x+5)}$ no existe si:","opts":["$x=1$ o $x=-5$","$x=3$","$x=0$","$x=-1$ o $x=5$"],"ans":0,"exp":"Paso 1: cada factor del piso $=0$. Paso 2: $x=1$ y $x=-5$. Paso 3: no cambies los signos de las raíces.","fig":null,"distractores":[{"opt":"$x=3$","error":"Leíste el número que se ve (el $9$, el $4$) como si fuera la raíz."},{"opt":"$x=0$","error":"Cancelaste un factor y borraste el hoyo del dominio original."},{"opt":"$x=-1$ o $x=5$","error":"Confundiste un cero del numerador con un hoyo."}],"d":"dificil","theory":{"lesson_id":"filtro-L02","lesson_title":"Dominio y hoyos","concept_title":"Dominio y hoyos","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-158","n":158,"fam":"domain","ch":"filtro-L02","t":"Dominio y hoyos","topics":["filtro-dominio"],"prompt":"Si $\\operatorname{sen}\\theta=\\dfrac{5}{4}$, en reales:","opts":["$\\cos\\theta=\\dfrac{3}{4}$","$\\cos\\theta=\\pm\\dfrac{3}{4}$","$\\theta=90^{\\circ}$","es imposible"],"ans":3,"exp":"Paso 1: $|\\operatorname{sen}\\theta|\\le 1$. Paso 2: $\\dfrac{5}{4}>1$. Paso 3: no hay $\\theta$ real. Inventar un coseno con Pitágoras es fingir que el seno era $\\dfrac{3}{5}$ o $\\dfrac{4}{5}$.","fig":null,"distractores":[{"opt":"$\\cos\\theta=\\dfrac{3}{4}$","error":"Leíste el número que se ve (el $9$, el $4$) como si fuera la raíz."},{"opt":"$\\cos\\theta=\\pm\\dfrac{3}{4}$","error":"Cancelaste un factor y borraste el hoyo del dominio original."},{"opt":"$\\theta=90^{\\circ}$","error":"Confundiste un cero del numerador con un hoyo."}],"d":"dificil","theory":{"lesson_id":"filtro-L02","lesson_title":"Dominio y hoyos","concept_title":"Dominio y hoyos","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-159","n":159,"fam":"domain","ch":"filtro-L02","t":"Dominio y hoyos","topics":["filtro-dominio"],"prompt":"El dominio de $\\sqrt{9-x^{2}}$ es:","opts":["$-3\\le x\\le 3$","$x\\ge 3$","$x\\le 9$","todos los reales"],"ans":0,"exp":"Paso 1: $9-x^{2}\\ge 0$ ⇒ $x^{2}\\le 9$. Paso 2: $-3\\le x\\le 3$. Paso 3: es el diametro del semicírculo, no $x\\ge 3$.","fig":null,"distractores":[{"opt":"$x\\ge 3$","error":"Leíste el número que se ve (el $9$, el $4$) como si fuera la raíz."},{"opt":"$x\\le 9$","error":"Cancelaste un factor y borraste el hoyo del dominio original."},{"opt":"todos los reales","error":"Confundiste un cero del numerador con un hoyo."}],"d":"dificil","theory":{"lesson_id":"filtro-L02","lesson_title":"Dominio y hoyos","concept_title":"Dominio y hoyos","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-160","n":160,"fam":"domain","ch":"filtro-L02","t":"Dominio y hoyos","topics":["filtro-dominio"],"prompt":"$\\dfrac{x^{2}-1}{x-1}$ vista como función original no está definida en:","opts":["$x=1$","$x=0$","está definida en todos lados porque se simplifica","$x=-1$"],"ans":0,"exp":"Paso 1: el piso original es $x-1$. Paso 2: hoyo en $x=1$. Paso 3: después de cancelar queda $x+1$ con un hueco: $f(1)$ no existía. El $-1$ anula el numerador, no el dominio.","fig":null,"distractores":[{"opt":"$x=0$","error":"Leíste el número que se ve (el $9$, el $4$) como si fuera la raíz."},{"opt":"está definida en todos lados porque se simplifica","error":"Cancelaste un factor y borraste el hoyo del dominio original."},{"opt":"$x=-1$","error":"Confundiste un cero del numerador con un hoyo."}],"d":"dificil","theory":{"lesson_id":"filtro-L02","lesson_title":"Dominio y hoyos","concept_title":"Dominio y hoyos","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-161","n":161,"fam":"congruence","ch":"filtro-L07","t":"Correspondencia y criterios","topics":["filtro-congruencia"],"prompt":"Si $\\triangle ACB \\cong \\triangle DFE$, el ángulo $\\angle B$ corresponde a:","opts":["$\\angle F$","$\\angle A$","$\\angle E$","$\\angle D$"],"ans":2,"exp":"Paso 1: el nombre es la lista: $A\\leftrightarrow D$, $C\\leftrightarrow F$, $B\\leftrightarrow E$. Paso 2: $B$ es la tercera letra y viaja con $E$. Paso 3: no mires “el de abajo a la izquierda” del dibujo.","fig":{"type":"filtro","name":"cong-acb-dfe"},"distractores":[{"opt":"$\\angle F$","error":"Emparejaste por la posición en el dibujo, no por el orden de las letras."},{"opt":"$\\angle A$","error":"Usaste un criterio que no copia (LLA o AAA)."},{"opt":"$\\angle D$","error":"Confundiste semejanza con congruencia."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Correspondencia y criterios","concept_title":"Correspondencia y criterios","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-162","n":162,"fam":"congruence","ch":"filtro-L07","t":"Correspondencia y criterios","topics":["filtro-congruencia"],"prompt":"Si $\\triangle ACB \\cong \\triangle DFE$, el lado $CB$ corresponde a:","opts":["$DF$","$ED$","$DE$","$FE$"],"ans":3,"exp":"Paso 1: $C\\leftrightarrow F$ y $B\\leftrightarrow E$. Paso 2: $CB\\leftrightarrow FE$. Paso 3: $DE$ es $AB$; $DF$ es $AC$.","fig":null,"distractores":[{"opt":"$DF$","error":"Emparejaste por la posición en el dibujo, no por el orden de las letras."},{"opt":"$ED$","error":"Usaste un criterio que no copia (LLA o AAA)."},{"opt":"$DE$","error":"Confundiste semejanza con congruencia."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Correspondencia y criterios","concept_title":"Correspondencia y criterios","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-163","n":163,"fam":"congruence","ch":"filtro-L07","t":"Correspondencia y criterios","topics":["filtro-congruencia"],"prompt":"Si $\\triangle PQR \\cong \\triangle XYZ$, $\\angle Q$ corresponde a:","opts":["$\\angle Y$","$\\angle Z$","$\\angle X$","$\\angle P$"],"ans":0,"exp":"Paso 1: segunda letra con segunda: $Q\\leftrightarrow Y$. Paso 2: no es $X$ (eso es $P$) ni $Z$ (eso es $R$). Paso 3: el orden del nombre manda.","fig":null,"distractores":[{"opt":"$\\angle Z$","error":"Emparejaste por la posición en el dibujo, no por el orden de las letras."},{"opt":"$\\angle X$","error":"Usaste un criterio que no copia (LLA o AAA)."},{"opt":"$\\angle P$","error":"Confundiste semejanza con congruencia."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Correspondencia y criterios","concept_title":"Correspondencia y criterios","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-164","n":164,"fam":"congruence","ch":"filtro-L07","t":"Correspondencia y criterios","topics":["filtro-congruencia"],"prompt":"Si $\\triangle ABC \\cong \\triangle CBA$, se puede afirmar que el triángulo es:","opts":["necesariamente equilátero","imposible","isósceles con $AB=CB$ (y más simetrías posibles)","necesariamente rectángulo"],"ans":2,"exp":"Paso 1: $A\\leftrightarrow C$, $B\\leftrightarrow B$, $C\\leftrightarrow A$. Paso 2: $AB\\leftrightarrow CB$, luego $AB=CB$. Paso 3: isósceles en $B$. Equilátero solo si además $AC=AB$.","fig":null,"distractores":[{"opt":"necesariamente equilátero","error":"Emparejaste por la posición en el dibujo, no por el orden de las letras."},{"opt":"imposible","error":"Usaste un criterio que no copia (LLA o AAA)."},{"opt":"necesariamente rectángulo","error":"Confundiste semejanza con congruencia."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Correspondencia y criterios","concept_title":"Correspondencia y criterios","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-165","n":165,"fam":"congruence","ch":"filtro-L07","t":"Correspondencia y criterios","topics":["filtro-congruencia"],"prompt":"¿Cuál criterio SÍ demuestra congruencia?","opts":["LLA (ángulo no incluido)","LAL (ángulo incluido)","dos lados cualesquiera","AAA"],"ans":1,"exp":"Paso 1: LAL, LLL y ALA sí. Paso 2: LLA es el caso ambiguo. Paso 3: AAA es semejanza, no copia.","fig":{"type":"filtro","name":"cong-rules"},"distractores":[{"opt":"LLA (ángulo no incluido)","error":"Emparejaste por la posición en el dibujo, no por el orden de las letras."},{"opt":"dos lados cualesquiera","error":"Usaste un criterio que no copia (LLA o AAA)."},{"opt":"AAA","error":"Confundiste semejanza con congruencia."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Correspondencia y criterios","concept_title":"Correspondencia y criterios","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-166","n":166,"fam":"congruence","ch":"filtro-L07","t":"Correspondencia y criterios","topics":["filtro-congruencia"],"prompt":"¿Cuál NO demuestra congruencia?","opts":["LLA","LAL","ALA","LLL"],"ans":0,"exp":"Paso 1: LLA (SSA) puede armar dos triángulos distintos. Paso 2: LLL, LAL y ALA sí copian. Paso 3: si el examen pregunta “cuál no”, casi siempre es LLA.","fig":null,"distractores":[{"opt":"LAL","error":"Emparejaste por la posición en el dibujo, no por el orden de las letras."},{"opt":"ALA","error":"Usaste un criterio que no copia (LLA o AAA)."},{"opt":"LLL","error":"Confundiste semejanza con congruencia."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Correspondencia y criterios","concept_title":"Correspondencia y criterios","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-167","n":167,"fam":"congruence","ch":"filtro-L07","t":"Correspondencia y criterios","topics":["filtro-congruencia"],"prompt":"AAA garantiza:","opts":["congruencia","que los lados son iguales","nada","semejanza, no congruencia"],"ans":3,"exp":"Paso 1: mismos ángulos ⇒ misma forma. Paso 2: el tamaño queda libre (fotocopia agrandada). Paso 3: para copia hace falta al menos un lado.","fig":null,"distractores":[{"opt":"congruencia","error":"Emparejaste por la posición en el dibujo, no por el orden de las letras."},{"opt":"que los lados son iguales","error":"Usaste un criterio que no copia (LLA o AAA)."},{"opt":"nada","error":"Confundiste semejanza con congruencia."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Correspondencia y criterios","concept_title":"Correspondencia y criterios","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-168","n":168,"fam":"congruence","ch":"filtro-L07","t":"Correspondencia y criterios","topics":["filtro-congruencia"],"prompt":"Si $\\triangle ABC \\sim \\triangle DEF$ (no congruentes) y $AB=6$, $DE=9$, $BC=8$, entonces $EF$ vale:","opts":["$8$","$12$","$4$","$11$"],"ans":1,"exp":"Paso 1: razón $\\dfrac{9}{6}=\\dfrac{3}{2}$. Paso 2: $EF=8\\cdot\\dfrac{3}{2}=12$. Paso 3: $BC$ viaja con $EF$ (2.ª–3.ª letras).","fig":null,"distractores":[{"opt":"$8$","error":"Emparejaste por la posición en el dibujo, no por el orden de las letras."},{"opt":"$4$","error":"Usaste un criterio que no copia (LLA o AAA)."},{"opt":"$11$","error":"Confundiste semejanza con congruencia."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Correspondencia y criterios","concept_title":"Correspondencia y criterios","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-169","n":169,"fam":"congruence","ch":"filtro-L07","t":"Correspondencia y criterios","topics":["filtro-congruencia"],"prompt":"Dos triángulos con lados $5,7,9$ y $5,7,8$ son:","opts":["congruentes por LAL","semejantes sí o sí","congruentes por LLL","ni congruentes ni (por LLL) iguales"],"ans":3,"exp":"Paso 1: LLL exige los tres lados iguales. Paso 2: $9\\neq 8$. Paso 3: las razones $5/5$, $7/7$, $9/8$ no coinciden: tampoco semejanza.","fig":null,"distractores":[{"opt":"congruentes por LAL","error":"Emparejaste por la posición en el dibujo, no por el orden de las letras."},{"opt":"semejantes sí o sí","error":"Usaste un criterio que no copia (LLA o AAA)."},{"opt":"congruentes por LLL","error":"Confundiste semejanza con congruencia."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Correspondencia y criterios","concept_title":"Correspondencia y criterios","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-170","n":170,"fam":"congruence","ch":"filtro-L07","t":"Correspondencia y criterios","topics":["filtro-congruencia"],"prompt":"En $\\triangle ABC \\cong \\triangle DEF$, si $AC=17$ y $AC$ mira a $\\angle B$, entonces el lado que mira a $\\angle E$ mide:","opts":["no se puede saber","$8{,}5$","el que mira a $\\angle D$","$17$"],"ans":3,"exp":"Paso 1: $B\\leftrightarrow E$. Paso 2: lo que mira a $B$ mira a $E$. Paso 3: ese lado es $17$.","fig":{"type":"filtro","name":"opp-same"},"distractores":[{"opt":"no se puede saber","error":"Emparejaste por la posición en el dibujo, no por el orden de las letras."},{"opt":"$8{,}5$","error":"Usaste un criterio que no copia (LLA o AAA)."},{"opt":"el que mira a $\\angle D$","error":"Confundiste semejanza con congruencia."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Correspondencia y criterios","concept_title":"Correspondencia y criterios","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-171","n":171,"fam":"congruence","ch":"filtro-L07","t":"Correspondencia y criterios","topics":["filtro-congruencia"],"prompt":"LAL exige que el ángulo esté:","opts":["incluido (entre los dos lados)","enfrente de uno de los lados","en cualquier vértice","siempre en $A$"],"ans":0,"exp":"Paso 1: LAL = lado-ángulo-lado, el ángulo del medio. Paso 2: si el ángulo no está entre esos lados, es LLA (ambiguo). Paso 3: el nombre del vértice no importa, importa la posición.","fig":null,"distractores":[{"opt":"enfrente de uno de los lados","error":"Emparejaste por la posición en el dibujo, no por el orden de las letras."},{"opt":"en cualquier vértice","error":"Usaste un criterio que no copia (LLA o AAA)."},{"opt":"siempre en $A$","error":"Confundiste semejanza con congruencia."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Correspondencia y criterios","concept_title":"Correspondencia y criterios","anchor":"h-la-regla-solo-esto"}}));
