  ALL.push(Q({"id":"fp-173","n":173,"fam":"congruence","ch":"filtro-L07","t":"Correspondencia y criterios","topics":["filtro-congruencia"],"prompt":"Un criterio válido de semejanza (no de congruencia) es:","opts":["LAL de copias iguales","HC","AA","LLL de copias iguales"],"ans":2,"exp":"Paso 1: dos ángulos iguales bastan para $\\sim$ (el tercero cae solo). Paso 2: LLL/LAL/HC con medidas iguales dan $\\cong$. Paso 3: no uses AAA como si fueran copias.","fig":null,"distractores":[{"opt":"LAL de copias iguales","error":"Emparejaste por la posición en el dibujo, no por el orden de las letras."},{"opt":"HC","error":"Usaste un criterio que no copia (LLA o AAA)."},{"opt":"LLL de copias iguales","error":"Confundiste semejanza con congruencia."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Correspondencia y criterios","concept_title":"Correspondencia y criterios","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-174","n":174,"fam":"congruence","ch":"filtro-L07","t":"Correspondencia y criterios","topics":["filtro-congruencia"],"prompt":"Si $\\triangle ABC \\cong \\triangle ACB$, el triángulo es:","opts":["isósceles con $AB=AC$","equilátero siempre","escaleno","rectángulo en $A$"],"ans":0,"exp":"Paso 1: $B\\leftrightarrow C$ y $C\\leftrightarrow B$. Paso 2: $AB\\leftrightarrow AC$. Paso 3: $AB=AC$, isósceles en $A$. Equilátero solo si también $BC=AB$.","fig":null,"distractores":[{"opt":"equilátero siempre","error":"Emparejaste por la posición en el dibujo, no por el orden de las letras."},{"opt":"escaleno","error":"Usaste un criterio que no copia (LLA o AAA)."},{"opt":"rectángulo en $A$","error":"Confundiste semejanza con congruencia."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Correspondencia y criterios","concept_title":"Correspondencia y criterios","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-175","n":175,"fam":"congruence","ch":"filtro-L07","t":"Correspondencia y criterios","topics":["filtro-congruencia"],"prompt":"AAL (dos ángulos y un lado no incluido):","opts":["solo da semejanza","hace falta Pitágoras","es inválido, como LLA","sí da congruencia, porque el tercer ángulo queda fijo y se vuelve ALA"],"ans":3,"exp":"Paso 1: dos ángulos ⇒ el tercero es $180$ menos la suma. Paso 2: ya tienes ALA. Paso 3: no es un cuarto caso que debas memorizar aparte; LLA sigue siendo el peligroso.","fig":null,"distractores":[{"opt":"solo da semejanza","error":"Emparejaste por la posición en el dibujo, no por el orden de las letras."},{"opt":"hace falta Pitágoras","error":"Usaste un criterio que no copia (LLA o AAA)."},{"opt":"es inválido, como LLA","error":"Confundiste semejanza con congruencia."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Correspondencia y criterios","concept_title":"Correspondencia y criterios","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-176","n":176,"fam":"congruence","ch":"filtro-L07","t":"Correspondencia y criterios","topics":["filtro-congruencia"],"prompt":"HC (hipotenusa y cateto) sirve solo si:","opts":["siempre, en cualquier triángulo","solo en equiláteros","hay un ángulo de $90^{\\circ}$","el triángulo es acutángulo"],"ans":2,"exp":"Paso 1: H y C hablan de hipotenusa. Paso 2: eso exige $90^{\\circ}$. Paso 3: si no ves el recto, no invoques HC.","fig":null,"distractores":[{"opt":"siempre, en cualquier triángulo","error":"Emparejaste por la posición en el dibujo, no por el orden de las letras."},{"opt":"solo en equiláteros","error":"Usaste un criterio que no copia (LLA o AAA)."},{"opt":"el triángulo es acutángulo","error":"Confundiste semejanza con congruencia."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Correspondencia y criterios","concept_title":"Correspondencia y criterios","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-177","n":177,"fam":"congruence","ch":"filtro-L07","t":"Correspondencia y criterios","topics":["filtro-congruencia"],"prompt":"Si $\\triangle ABC \\sim \\triangle DEF$ con razón $2:5$ y el perímetro de $ABC$ es $14$, el de $DEF$ es:","opts":["$35$","$28$","$19$","$7$"],"ans":0,"exp":"Paso 1: los perímetros van en la misma razón que los lados. Paso 2: $14\\cdot\\dfrac{5}{2}=35$. Paso 3: no sumes $2+5$ al perímetro.","fig":null,"distractores":[{"opt":"$28$","error":"Emparejaste por la posición en el dibujo, no por el orden de las letras."},{"opt":"$19$","error":"Usaste un criterio que no copia (LLA o AAA)."},{"opt":"$7$","error":"Confundiste semejanza con congruencia."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Correspondencia y criterios","concept_title":"Correspondencia y criterios","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-178","n":178,"fam":"congruence","ch":"filtro-L07","t":"Correspondencia y criterios","topics":["filtro-congruencia"],"prompt":"$\\triangle ABC$ tiene $AB=c$, $BC=a$, $CA=b$. Si $\\triangle ABC \\cong \\triangle BCA$, entonces:","opts":["solo rectángulo","nada se puede decir","solo $a=b$","$a=b=c$ (equilátero)"],"ans":3,"exp":"Paso 1: $A\\leftrightarrow B$, $B\\leftrightarrow C$, $C\\leftrightarrow A$. Paso 2: $AB=BC$, $BC=CA$, $CA=AB$. Paso 3: los tres iguales.","fig":null,"distractores":[{"opt":"solo rectángulo","error":"Emparejaste por la posición en el dibujo, no por el orden de las letras."},{"opt":"nada se puede decir","error":"Usaste un criterio que no copia (LLA o AAA)."},{"opt":"solo $a=b$","error":"Confundiste semejanza con congruencia."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Correspondencia y criterios","concept_title":"Correspondencia y criterios","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-179","n":179,"fam":"congruence","ch":"filtro-L07","t":"Correspondencia y criterios","topics":["filtro-congruencia"],"prompt":"Dos triángulos rectángulos con un agudo de $37^{\\circ}$ cada uno son:","opts":["congruentes siempre","solo isósceles","semejantes (AA)","nada en común"],"ans":2,"exp":"Paso 1: $90^{\\circ}$ común y $37^{\\circ}$ común. Paso 2: AA ⇒ $\\sim$. Paso 3: sin un lado igual, no hay $\\cong$.","fig":null,"distractores":[{"opt":"congruentes siempre","error":"Emparejaste por la posición en el dibujo, no por el orden de las letras."},{"opt":"solo isósceles","error":"Usaste un criterio que no copia (LLA o AAA)."},{"opt":"nada en común","error":"Confundiste semejanza con congruencia."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Correspondencia y criterios","concept_title":"Correspondencia y criterios","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-180","n":180,"fam":"congruence","ch":"filtro-L07","t":"Correspondencia y criterios","topics":["filtro-congruencia"],"prompt":"Si $\\angle A \\cong \\angle D$, $\\angle B \\cong \\angle E$ y $AB=DE$, los triángulos $ABC$ y $DEF$ son:","opts":["congruentes por ALA (el lado $AB$ está entre $A$ y $B$)","solo semejantes","congruentes por LAL","insuficiente"],"ans":0,"exp":"Paso 1: ángulos $A,B$ y el lado que los une $AB$. Paso 2: eso es ALA. Paso 3: LAL sería dos lados y el ángulo del medio.","fig":null,"distractores":[{"opt":"solo semejantes","error":"Emparejaste por la posición en el dibujo, no por el orden de las letras."},{"opt":"congruentes por LAL","error":"Usaste un criterio que no copia (LLA o AAA)."},{"opt":"insuficiente","error":"Confundiste semejanza con congruencia."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Correspondencia y criterios","concept_title":"Correspondencia y criterios","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-181","n":181,"fam":"similarity","ch":"filtro-L07","t":"Semejanza y altura a la hipotenusa","topics":["filtro-semejanza"],"prompt":"En un triángulo rectángulo de catetos $3$ y $4$ e hipotenusa $5$, la altura sobre la hipotenusa mide:","opts":["$\\dfrac{7}{2}$","$\\dfrac{5}{2}$","$3$","$\\dfrac{12}{5}$"],"ans":3,"exp":"Paso 1: área de dos modos: $\\dfrac{3\\cdot4}{2}=\\dfrac{5\\cdot h}{2}$. Paso 2: $h=\\dfrac{12}{5}$. Paso 3: también $h^{2}=$ producto de los dos segmentos de la hipotenusa.","fig":{"type":"filtro","name":"alt-hyp"},"distractores":[{"opt":"$\\dfrac{7}{2}$","error":"Usaste un cateto o la mitad de la hipotenusa en vez de la media geométrica."},{"opt":"$\\dfrac{5}{2}$","error":"Confundiste la altura con la proyección de un cateto."},{"opt":"$3$","error":"Llamaste congruencia a lo que solo es semejanza."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Semejanza y altura a la hipotenusa","concept_title":"Semejanza y altura a la hipotenusa","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-182","n":182,"fam":"similarity","ch":"filtro-L07","t":"Semejanza y altura a la hipotenusa","topics":["filtro-semejanza"],"prompt":"Rectángulo en $C$, catetos $AC=5$, $BC=12$, hipotenusa $AB=13$. El segmento de la hipotenusa adyacente a $A$ (proyección de $AC$) mide:","opts":["$\\dfrac{60}{13}$","$\\dfrac{144}{13}$","$5$","$\\dfrac{25}{13}$"],"ans":3,"exp":"Paso 1: $\\triangle AC\\text{-hip} \\sim \\triangle ABC$. Paso 2: $\\dfrac{AC}{AB}=\\dfrac{AD}{AC}$ ⇒ $AC^{2}=AD\\cdot AB$. Paso 3: $AD=\\dfrac{5^{2}}{13}=\\dfrac{25}{13}$.","fig":{"type":"filtro","name":"alt-hyp"},"distractores":[{"opt":"$\\dfrac{60}{13}$","error":"Usaste un cateto o la mitad de la hipotenusa en vez de la media geométrica."},{"opt":"$\\dfrac{144}{13}$","error":"Confundiste la altura con la proyección de un cateto."},{"opt":"$5$","error":"Llamaste congruencia a lo que solo es semejanza."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Semejanza y altura a la hipotenusa","concept_title":"Semejanza y altura a la hipotenusa","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-183","n":183,"fam":"similarity","ch":"filtro-L07","t":"Semejanza y altura a la hipotenusa","topics":["filtro-semejanza"],"prompt":"En el triángulo rectángulo de catetos $8$, $15$ e hipotenusa $17$, los tres triángulos que arma la altura sobre la hipotenusa son:","opts":["solo congruentes","equiláteros","nada que ver","semejantes entre sí (y al grande)"],"ans":3,"exp":"Paso 1: cada triángulo chico comparte un agudo con el grande. Paso 2: AA ⇒ los tres $\\sim$. Paso 3: no son copias (salvo isósceles $45$-$45$-$90$).","fig":{"type":"filtro","name":"alt-hyp"},"distractores":[{"opt":"solo congruentes","error":"Usaste un cateto o la mitad de la hipotenusa en vez de la media geométrica."},{"opt":"equiláteros","error":"Confundiste la altura con la proyección de un cateto."},{"opt":"nada que ver","error":"Llamaste congruencia a lo que solo es semejanza."}],"d":"dificil","theory":{"lesson_id":"filtro-L07","lesson_title":"Semejanza y altura a la hipotenusa","concept_title":"Semejanza y altura a la hipotenusa","anchor":"h-la-regla-solo-esto"}}));
