  ALL.push(Q({"id":"fp-191","n":191,"fam":"parallels","ch":"filtro-L06","t":"Paralelas, exteriores y lados","topics":["filtro-angulos"],"prompt":"Dos rectas paralelas cortadas por una transversal. $\\alpha$ es el ángulo exterior superior derecho y $\\beta$ el exterior inferior izquierdo. Se puede afirmar que:","opts":["$\\alpha=2\\beta$","$\\alpha+\\beta=180^{\\circ}$","$\\alpha=\\beta$ (alternos externos)","$\\alpha+\\beta=90^{\\circ}$"],"ans":2,"exp":"Paso 1: alternos externos están en lados distintos de la transversal y fuera de la franja. Paso 2: con paralelas, son iguales. Paso 3: quienes suman $180^{\\circ}$ son los colaterales internos.","fig":{"type":"filtro","name":"par-alpha-beta"},"distractores":[{"opt":"$\\alpha=2\\beta$","error":"Confundiste correspondientes (iguales) con colaterales (suman $180^{\\circ}$)."},{"opt":"$\\alpha+\\beta=180^{\\circ}$","error":"Tomaste el exterior como $180$ menos un solo vecino."},{"opt":"$\\alpha+\\beta=90^{\\circ}$","error":"Invertiste “ángulo grande mira lado grande”."}],"d":"dificil","theory":{"lesson_id":"filtro-L06","lesson_title":"Paralelas, exteriores y lados","concept_title":"Paralelas, exteriores y lados","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-192","n":192,"fam":"parallels","ch":"filtro-L06","t":"Paralelas, exteriores y lados","topics":["filtro-angulos"],"prompt":"Entre paralelas, dos colaterales internos de $3x+10$ y $2x+20$ (grados) dan $x$ igual a:","opts":["$10$","$30$","$40$","$18$"],"ans":1,"exp":"Paso 1: colaterales internos suman $180^{\\circ}$. Paso 2: $5x+30=180$. Paso 3: $5x=150$, $x=30$. Si los igualas, estás pensando en correspondientes.","fig":null,"distractores":[{"opt":"$10$","error":"Confundiste correspondientes (iguales) con colaterales (suman $180^{\\circ}$)."},{"opt":"$40$","error":"Tomaste el exterior como $180$ menos un solo vecino."},{"opt":"$18$","error":"Invertiste “ángulo grande mira lado grande”."}],"d":"dificil","theory":{"lesson_id":"filtro-L06","lesson_title":"Paralelas, exteriores y lados","concept_title":"Paralelas, exteriores y lados","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-193","n":193,"fam":"parallels","ch":"filtro-L06","t":"Paralelas, exteriores y lados","topics":["filtro-angulos"],"prompt":"Correspondientes entre paralelas miden $4x-5$ y $3x+15$. Entonces $x$ vale:","opts":["$20$","$36$","$10$","$5$"],"ans":0,"exp":"Paso 1: correspondientes son iguales. Paso 2: $4x-5=3x+15$. Paso 3: $x=20$. Si sumas $180$, los trataste como colaterales.","fig":null,"distractores":[{"opt":"$36$","error":"Confundiste correspondientes (iguales) con colaterales (suman $180^{\\circ}$)."},{"opt":"$10$","error":"Tomaste el exterior como $180$ menos un solo vecino."},{"opt":"$5$","error":"Invertiste “ángulo grande mira lado grande”."}],"d":"dificil","theory":{"lesson_id":"filtro-L06","lesson_title":"Paralelas, exteriores y lados","concept_title":"Paralelas, exteriores y lados","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-194","n":194,"fam":"parallels","ch":"filtro-L06","t":"Paralelas, exteriores y lados","topics":["filtro-angulos"],"prompt":"Un par de opuestos por el vértice mide $2x+7$ y $5x-20$. $x$ vale:","opts":["$13$","$4$","$9$","$27$"],"ans":2,"exp":"Paso 1: opuestos por el vértice son iguales (no hace falta paralelas). Paso 2: $2x+7=5x-20$. Paso 3: $27=3x$, $x=9$.","fig":null,"distractores":[{"opt":"$13$","error":"Confundiste correspondientes (iguales) con colaterales (suman $180^{\\circ}$)."},{"opt":"$4$","error":"Tomaste el exterior como $180$ menos un solo vecino."},{"opt":"$27$","error":"Invertiste “ángulo grande mira lado grande”."}],"d":"dificil","theory":{"lesson_id":"filtro-L06","lesson_title":"Paralelas, exteriores y lados","concept_title":"Paralelas, exteriores y lados","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-195","n":195,"fam":"parallels","ch":"filtro-L06","t":"Paralelas, exteriores y lados","topics":["filtro-angulos"],"prompt":"El exterior de un triángulo, alargando un lado, mide:","opts":["$180^{\\circ}$ menos el ángulo vecino solamente","el triple del menor","siempre $90^{\\circ}$","la suma de los dos interiores que no lo tocan"],"ans":3,"exp":"Paso 1: interiores suman $180$. Paso 2: el llano en el vértice también. Paso 3: el exterior $= $ los dos lejanos. Atajo: no hace falta hallar el tercero.","fig":{"type":"filtro","name":"exterior-angle"},"distractores":[{"opt":"$180^{\\circ}$ menos el ángulo vecino solamente","error":"Confundiste correspondientes (iguales) con colaterales (suman $180^{\\circ}$)."},{"opt":"el triple del menor","error":"Tomaste el exterior como $180$ menos un solo vecino."},{"opt":"siempre $90^{\\circ}$","error":"Invertiste “ángulo grande mira lado grande”."}],"d":"dificil","theory":{"lesson_id":"filtro-L06","lesson_title":"Paralelas, exteriores y lados","concept_title":"Paralelas, exteriores y lados","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-196","n":196,"fam":"parallels","ch":"filtro-L06","t":"Paralelas, exteriores y lados","topics":["filtro-angulos"],"prompt":"Interiores de un triángulo $2x$, $3x$ y $4x$. El mayor mide:","opts":["$120^{\\circ}$","$80^{\\circ}$","$90^{\\circ}$","$40^{\\circ}$"],"ans":1,"exp":"Paso 1: $9x=180$, $x=20$. Paso 2: el mayor es $4x=80^{\\circ}$. Paso 3: no es rectángulo.","fig":null,"distractores":[{"opt":"$120^{\\circ}$","error":"Confundiste correspondientes (iguales) con colaterales (suman $180^{\\circ}$)."},{"opt":"$90^{\\circ}$","error":"Tomaste el exterior como $180$ menos un solo vecino."},{"opt":"$40^{\\circ}$","error":"Invertiste “ángulo grande mira lado grande”."}],"d":"dificil","theory":{"lesson_id":"filtro-L06","lesson_title":"Paralelas, exteriores y lados","concept_title":"Paralelas, exteriores y lados","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-197","n":197,"fam":"parallels","ch":"filtro-L06","t":"Paralelas, exteriores y lados","topics":["filtro-angulos"],"prompt":"Un ángulo interior de $70^{\\circ}$ y otro de $45^{\\circ}$. El exterior en el tercer vértice mide:","opts":["$110^{\\circ}$","$25^{\\circ}$","$115^{\\circ}$","$65^{\\circ}$"],"ans":2,"exp":"Paso 1: atajo, exterior $=$ los dos lejanos $70+45=115$. Paso 2: el interior del tercer vértice sería $65$, y $180-65=115$. Paso 3: $110$ es un $180-70$ a medias.","fig":null,"distractores":[{"opt":"$110^{\\circ}$","error":"Confundiste correspondientes (iguales) con colaterales (suman $180^{\\circ}$)."},{"opt":"$25^{\\circ}$","error":"Tomaste el exterior como $180$ menos un solo vecino."},{"opt":"$65^{\\circ}$","error":"Invertiste “ángulo grande mira lado grande”."}],"d":"dificil","theory":{"lesson_id":"filtro-L06","lesson_title":"Paralelas, exteriores y lados","concept_title":"Paralelas, exteriores y lados","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-198","n":198,"fam":"parallels","ch":"filtro-L06","t":"Paralelas, exteriores y lados","topics":["filtro-angulos"],"prompt":"Si $AB\\parallel CD$ y una transversal forma $65^{\\circ}$ con $AB$, el correspondiente en $CD$ mide:","opts":["$115^{\\circ}$","$90^{\\circ}$","$25^{\\circ}$","$65^{\\circ}$"],"ans":3,"exp":"Paso 1: correspondientes iguales. Paso 2: $65^{\\circ}$. Paso 3: $115$ sería el colateral ($180-65$).","fig":{"type":"filtro","name":"right-angles-perp"},"distractores":[{"opt":"$115^{\\circ}$","error":"Confundiste correspondientes (iguales) con colaterales (suman $180^{\\circ}$)."},{"opt":"$90^{\\circ}$","error":"Tomaste el exterior como $180$ menos un solo vecino."},{"opt":"$25^{\\circ}$","error":"Invertiste “ángulo grande mira lado grande”."}],"d":"dificil","theory":{"lesson_id":"filtro-L06","lesson_title":"Paralelas, exteriores y lados","concept_title":"Paralelas, exteriores y lados","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-199","n":199,"fam":"parallels","ch":"filtro-L06","t":"Paralelas, exteriores y lados","topics":["filtro-angulos"],"prompt":"Tres exteriores de un triángulo (uno por vértice) suman:","opts":["$270^{\\circ}$","$90^{\\circ}$","$180^{\\circ}$","$360^{\\circ}$"],"ans":3,"exp":"Paso 1: cada exterior $= $ suma de los dos interiores lejanos. Paso 2: al sumar los tres, cada interior aparece dos veces: $2\\cdot 180=360$. Paso 3: no suman $180$.","fig":null,"distractores":[{"opt":"$270^{\\circ}$","error":"Confundiste correspondientes (iguales) con colaterales (suman $180^{\\circ}$)."},{"opt":"$90^{\\circ}$","error":"Tomaste el exterior como $180$ menos un solo vecino."},{"opt":"$180^{\\circ}$","error":"Invertiste “ángulo grande mira lado grande”."}],"d":"dificil","theory":{"lesson_id":"filtro-L06","lesson_title":"Paralelas, exteriores y lados","concept_title":"Paralelas, exteriores y lados","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-200","n":200,"fam":"parallels","ch":"filtro-L06","t":"Paralelas, exteriores y lados","topics":["filtro-angulos"],"prompt":"El lado más largo de un triángulo queda frente a:","opts":["el ángulo más chico","un ángulo de $60^{\\circ}$","el ángulo más grande","siempre al $90^{\\circ}$"],"ans":2,"exp":"Paso 1: ángulo grande $\\leftrightarrow$ lado de enfrente grande. Paso 2: solo si hay $90^{\\circ}$ el lado más largo es la hipotenusa. Paso 3: en un acutángulo no hay hipotenusa.","fig":{"type":"filtro","name":"bigger-side"},"distractores":[{"opt":"el ángulo más chico","error":"Confundiste correspondientes (iguales) con colaterales (suman $180^{\\circ}$)."},{"opt":"un ángulo de $60^{\\circ}$","error":"Tomaste el exterior como $180$ menos un solo vecino."},{"opt":"siempre al $90^{\\circ}$","error":"Invertiste “ángulo grande mira lado grande”."}],"d":"dificil","theory":{"lesson_id":"filtro-L06","lesson_title":"Paralelas, exteriores y lados","concept_title":"Paralelas, exteriores y lados","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-201","n":201,"fam":"thales","ch":"filtro-L06","t":"Tales numérico","topics":["filtro-tales"],"prompt":"Un rayo desde $O$ corta dos paralelas: el tramo corto mide $2$ y el total hasta la segunda es $8$. Otro rayo tiene tramo corto $3$. El tramo largo de ese segundo rayo mide:","opts":["$12$","$6$","$\\dfrac{3}{4}$","$9$"],"ans":3,"exp":"Paso 1: Tales $\\dfrac{OA'}{OA}=\\dfrac{OB'}{OB}$ ⇒ $\\dfrac{2}{8}=\\dfrac{3}{OB}$. Paso 2: $OB=\\dfrac{3\\cdot8}{2}=12$. Paso 3: el tramo largo es $OB-3=9$. No restes los cortos a ciegas.","fig":{"type":"filtro","name":"thales"},"distractores":[{"opt":"$12$","error":"Eso es el total OB, no el tramo largo OB menos el corto."},{"opt":"$6$","error":"Sumaste la diferencia del primer rayo al corto del segundo (no es Tales)."},{"opt":"$\\dfrac{3}{4}$","error":"Invertiste la proporción."}],"d":"dificil","theory":{"lesson_id":"filtro-L06","lesson_title":"Tales numérico","concept_title":"Tales numérico","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-202","n":202,"fam":"thales","ch":"filtro-L06","t":"Tales numérico","topics":["filtro-tales"],"prompt":"Un rayo desde $O$ corta dos paralelas: el tramo corto mide $3$ y el total hasta la segunda es $12$. Otro rayo tiene tramo corto $5$. El tramo largo de ese segundo rayo mide:","opts":["$14$","$\\dfrac{5}{4}$","$20$","$15$"],"ans":3,"exp":"Paso 1: Tales $\\dfrac{OA'}{OA}=\\dfrac{OB'}{OB}$ ⇒ $\\dfrac{3}{12}=\\dfrac{5}{OB}$. Paso 2: $OB=\\dfrac{5\\cdot12}{3}=20$. Paso 3: el tramo largo es $OB-5=15$. No restes los cortos a ciegas.","fig":{"type":"filtro","name":"thales"},"distractores":[{"opt":"$14$","error":"Eso es el total OB, no el tramo largo OB menos el corto."},{"opt":"$\\dfrac{5}{4}$","error":"Sumaste la diferencia del primer rayo al corto del segundo (no es Tales)."},{"opt":"$20$","error":"Invertiste la proporción."}],"d":"dificil","theory":{"lesson_id":"filtro-L06","lesson_title":"Tales numérico","concept_title":"Tales numérico","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-203","n":203,"fam":"thales","ch":"filtro-L06","t":"Tales numérico","topics":["filtro-tales"],"prompt":"Un rayo desde $O$ corta dos paralelas: el tramo corto mide $4$ y el total hasta la segunda es $10$. Otro rayo tiene tramo corto $6$. El tramo largo de ese segundo rayo mide:","opts":["$15$","$\\dfrac{12}{5}$","$9$","$12$"],"ans":2,"exp":"Paso 1: Tales $\\dfrac{OA'}{OA}=\\dfrac{OB'}{OB}$ ⇒ $\\dfrac{4}{10}=\\dfrac{6}{OB}$. Paso 2: $OB=\\dfrac{6\\cdot10}{4}=15$. Paso 3: el tramo largo es $OB-6=9$. No restes los cortos a ciegas.","fig":{"type":"filtro","name":"thales"},"distractores":[{"opt":"$15$","error":"Eso es el total OB, no el tramo largo OB menos el corto."},{"opt":"$\\dfrac{12}{5}$","error":"Sumaste la diferencia del primer rayo al corto del segundo (no es Tales)."},{"opt":"$12$","error":"Invertiste la proporción."}],"d":"dificil","theory":{"lesson_id":"filtro-L06","lesson_title":"Tales numérico","concept_title":"Tales numérico","anchor":"h-la-regla-solo-esto"}}));
