  ALL.push(Q({"id":"fp-207","n":207,"fam":"thales","ch":"filtro-L06","t":"Tales numérico","topics":["filtro-tales"],"prompt":"Un rayo desde $O$ corta dos paralelas: el tramo corto mide $3$ y el total hasta la segunda es $9$. Otro rayo tiene tramo corto $7$. El tramo largo de ese segundo rayo mide:","opts":["$14$","$\\dfrac{7}{3}$","$13$","$21$"],"ans":0,"exp":"Paso 1: Tales $\\dfrac{OA'}{OA}=\\dfrac{OB'}{OB}$ ⇒ $\\dfrac{3}{9}=\\dfrac{7}{OB}$. Paso 2: $OB=\\dfrac{7\\cdot9}{3}=21$. Paso 3: el tramo largo es $OB-7=14$. No restes los cortos a ciegas.","fig":{"type":"filtro","name":"thales"},"distractores":[{"opt":"$\\dfrac{7}{3}$","error":"Eso es el total OB, no el tramo largo OB menos el corto."},{"opt":"$13$","error":"Sumaste la diferencia del primer rayo al corto del segundo (no es Tales)."},{"opt":"$21$","error":"Invertiste la proporción."}],"d":"dificil","theory":{"lesson_id":"filtro-L06","lesson_title":"Tales numérico","concept_title":"Tales numérico","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-208","n":208,"fam":"thales","ch":"filtro-L06","t":"Tales numérico","topics":["filtro-tales"],"prompt":"Un rayo desde $O$ corta dos paralelas: el tramo corto mide $4$ y el total hasta la segunda es $14$. Otro rayo tiene tramo corto $6$. El tramo largo de ese segundo rayo mide:","opts":["$\\dfrac{12}{7}$","$15$","$21$","$16$"],"ans":1,"exp":"Paso 1: Tales $\\dfrac{OA'}{OA}=\\dfrac{OB'}{OB}$ ⇒ $\\dfrac{4}{14}=\\dfrac{6}{OB}$. Paso 2: $OB=\\dfrac{6\\cdot14}{4}=21$. Paso 3: el tramo largo es $OB-6=15$. No restes los cortos a ciegas.","fig":{"type":"filtro","name":"thales"},"distractores":[{"opt":"$\\dfrac{12}{7}$","error":"Eso es el total OB, no el tramo largo OB menos el corto."},{"opt":"$21$","error":"Sumaste la diferencia del primer rayo al corto del segundo (no es Tales)."},{"opt":"$16$","error":"Invertiste la proporción."}],"d":"dificil","theory":{"lesson_id":"filtro-L06","lesson_title":"Tales numérico","concept_title":"Tales numérico","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-209","n":209,"fam":"thales","ch":"filtro-L06","t":"Tales numérico","topics":["filtro-tales"],"prompt":"Un rayo desde $O$ corta dos paralelas: el tramo corto mide $5$ y el total hasta la segunda es $8$. Otro rayo tiene tramo corto $10$. El tramo largo de ese segundo rayo mide:","opts":["$16$","$13$","$\\dfrac{25}{4}$","$6$"],"ans":3,"exp":"Paso 1: Tales $\\dfrac{OA'}{OA}=\\dfrac{OB'}{OB}$ ⇒ $\\dfrac{5}{8}=\\dfrac{10}{OB}$. Paso 2: $OB=\\dfrac{10\\cdot8}{5}=16$. Paso 3: el tramo largo es $OB-10=6$. No restes los cortos a ciegas.","fig":{"type":"filtro","name":"thales"},"distractores":[{"opt":"$16$","error":"Eso es el total OB, no el tramo largo OB menos el corto."},{"opt":"$13$","error":"Sumaste la diferencia del primer rayo al corto del segundo (no es Tales)."},{"opt":"$\\dfrac{25}{4}$","error":"Invertiste la proporción."}],"d":"dificil","theory":{"lesson_id":"filtro-L06","lesson_title":"Tales numérico","concept_title":"Tales numérico","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-210","n":210,"fam":"thales","ch":"filtro-L06","t":"Tales numérico","topics":["filtro-tales"],"prompt":"Un rayo desde $O$ corta dos paralelas: el tramo corto mide $2$ y el total hasta la segunda es $5$. Otro rayo tiene tramo corto $8$. El tramo largo de ese segundo rayo mide:","opts":["$20$","$\\dfrac{16}{5}$","$11$","$12$"],"ans":3,"exp":"Paso 1: Tales $\\dfrac{OA'}{OA}=\\dfrac{OB'}{OB}$ ⇒ $\\dfrac{2}{5}=\\dfrac{8}{OB}$. Paso 2: $OB=\\dfrac{8\\cdot5}{2}=20$. Paso 3: el tramo largo es $OB-8=12$. No restes los cortos a ciegas.","fig":{"type":"filtro","name":"thales"},"distractores":[{"opt":"$20$","error":"Eso es el total OB, no el tramo largo OB menos el corto."},{"opt":"$\\dfrac{16}{5}$","error":"Sumaste la diferencia del primer rayo al corto del segundo (no es Tales)."},{"opt":"$11$","error":"Invertiste la proporción."}],"d":"dificil","theory":{"lesson_id":"filtro-L06","lesson_title":"Tales numérico","concept_title":"Tales numérico","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-211","n":211,"fam":"cosines","ch":"filtro-L08","t":"Ley de cosenos (valor)","topics":["filtro-cosenos"],"prompt":"En un triángulo con $a=5$, $b=7$, $c=7$, $\\cos A$ vale:","opts":["$\\dfrac{73}{98}$","$\\dfrac{123}{98}$","$\\dfrac{73}{49}$","$\\dfrac{5}{14}$"],"ans":0,"exp":"Paso 1: $\\cos A=\\dfrac{b^{2}+c^{2}-a^{2}}{2bc}$. Paso 2: numerador 7^{2}+7^{2}-5^{2}=73. Paso 3: denominador $2\\cdot7\\cdot7=98$. Queda $\\dfrac{73}{98}$. El lado que se resta es el de enfrente de $A$.","fig":{"type":"filtro","name":"law-cosines"},"distractores":[{"opt":"$\\dfrac{123}{98}$","error":"Restaste otro lado (el de enfrente de $C$ o $B$)."},{"opt":"$\\dfrac{73}{49}$","error":"Escribiste $+a^{2}$ en vez de $-a^{2}$."},{"opt":"$\\dfrac{5}{14}$","error":"Te olvidaste del $2$ del denominador."}],"d":"dificil","theory":{"lesson_id":"filtro-L08","lesson_title":"Ley de cosenos (valor)","concept_title":"Ley de cosenos (valor)","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-212","n":212,"fam":"cosines","ch":"filtro-L08","t":"Ley de cosenos (forma)","topics":["filtro-cosenos"],"prompt":"Con lados $a=6$, $b=8$, $c=8$, la forma correcta de $\\cos A$ es:","opts":["$\\dfrac{a^{2}+b^{2}-c^{2}}{2ab}$","$\\dfrac{a}{b+c}$","$\\dfrac{b^{2}+c^{2}-a^{2}}{2bc}$","$\\dfrac{b^{2}+c^{2}+a^{2}}{2bc}$"],"ans":2,"exp":"Paso 1: el lado que se resta es el opuesto al ángulo. Paso 2: opuesto a $A$ es $a$. Paso 3: denominador $2bc$ (los otros dos). La opción con $+a^{2}$ cambia el signo de cosenos.","fig":{"type":"filtro","name":"law-cosines"},"distractores":[{"opt":"$\\dfrac{a^{2}+b^{2}-c^{2}}{2ab}$","error":"Esa es la forma de $\\cos C$, no de $\\cos A$."},{"opt":"$\\dfrac{a}{b+c}$","error":"El signo del $a^{2}$ es menos, no más."},{"opt":"$\\dfrac{b^{2}+c^{2}+a^{2}}{2bc}$","error":"Eso no es la ley de cosenos."}],"d":"dificil","theory":{"lesson_id":"filtro-L08","lesson_title":"Ley de cosenos (forma)","concept_title":"Ley de cosenos (forma)","anchor":"h-la-regla-solo-esto"}}));
