  ALL.push(Q({"id":"fp-222","n":222,"fam":"sines-pit","ch":"filtro-L08","t":"Pitágoras, notables y senos","topics":["filtro-pitagoras"],"prompt":"Lados $6$, $8$, $11$. El triángulo es:","opts":["obtusángulo","imposible","acutángulo","rectángulo"],"ans":0,"exp":"Paso 1: $6^{2}+8^{2}=36+64=100$, $11^{2}=121>100$. Paso 2: $c^{2}>a^{2}+b^{2}$ ⇒ obtuso. Paso 3: si fuera $10$ sería rectángulo ($6$-$8$-$10$).","fig":null,"distractores":[{"opt":"imposible","error":"Aplicaste la plantilla del notable equivocado ($30$ vs $45$)."},{"opt":"acutángulo","error":"Confundiste seno con coseno o con tangente."},{"opt":"rectángulo","error":"Usaste Pitágoras o cosenos cuando el par ángulo+opuesto pedía senos."}],"d":"dificil","theory":{"lesson_id":"filtro-L08","lesson_title":"Pitágoras, notables y senos","concept_title":"Pitágoras, notables y senos","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-223","n":223,"fam":"sines-pit","ch":"filtro-L08","t":"Pitágoras, notables y senos","topics":["filtro-pitagoras"],"prompt":"Lados $5$, $7$, $8$. El triángulo es:","opts":["acutángulo","obtusángulo","rectángulo","imposible"],"ans":0,"exp":"Paso 1: $5^{2}+7^{2}=25+49=74$, $8^{2}=64<74$. Paso 2: también $5^{2}+8^{2}>7^{2}$ y $7^{2}+8^{2}>5^{2}$. Paso 3: los tres $c^{2}<a^{2}+b^{2}$ ⇒ acutángulo.","fig":null,"distractores":[{"opt":"obtusángulo","error":"Aplicaste la plantilla del notable equivocado ($30$ vs $45$)."},{"opt":"rectángulo","error":"Confundiste seno con coseno o con tangente."},{"opt":"imposible","error":"Usaste Pitágoras o cosenos cuando el par ángulo+opuesto pedía senos."}],"d":"dificil","theory":{"lesson_id":"filtro-L08","lesson_title":"Pitágoras, notables y senos","concept_title":"Pitágoras, notables y senos","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-224","n":224,"fam":"sines-pit","ch":"filtro-L08","t":"Pitágoras, notables y senos","topics":["filtro-pitagoras"],"prompt":"En un $30^{\\circ}$-$60^{\\circ}$-$90^{\\circ}$ la hipotenusa es $14$. El lado frente al $30^{\\circ}$ mide:","opts":["$14\\sqrt{3}$","$7\\sqrt{3}$","$7$","$28$"],"ans":2,"exp":"Paso 1: frente al $30^{\\circ}$ va la mitad de la hipotenusa. Paso 2: $7$. Paso 3: $7\\sqrt{3}$ es el frente al $60^{\\circ}$.","fig":null,"distractores":[{"opt":"$14\\sqrt{3}$","error":"Aplicaste la plantilla del notable equivocado ($30$ vs $45$)."},{"opt":"$7\\sqrt{3}$","error":"Confundiste seno con coseno o con tangente."},{"opt":"$28$","error":"Usaste Pitágoras o cosenos cuando el par ángulo+opuesto pedía senos."}],"d":"dificil","theory":{"lesson_id":"filtro-L08","lesson_title":"Pitágoras, notables y senos","concept_title":"Pitágoras, notables y senos","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-225","n":225,"fam":"sines-pit","ch":"filtro-L08","t":"Pitágoras, notables y senos","topics":["filtro-pitagoras"],"prompt":"En un $45^{\\circ}$-$45^{\\circ}$-$90^{\\circ}$ un cateto mide $5$. La hipotenusa es:","opts":["$5\\sqrt{3}$","$\\dfrac{5}{\\sqrt{2}}$ visto como $5$","$10$","$5\\sqrt{2}$"],"ans":3,"exp":"Paso 1: plantilla $a$, $a$, $a\\sqrt{2}$. Paso 2: hipotenusa $5\\sqrt{2}$. Paso 3: $5\\sqrt{3}$ es de la plantilla $30$-$60$-$90$.","fig":null,"distractores":[{"opt":"$5\\sqrt{3}$","error":"Aplicaste la plantilla del notable equivocado ($30$ vs $45$)."},{"opt":"$\\dfrac{5}{\\sqrt{2}}$ visto como $5$","error":"Confundiste seno con coseno o con tangente."},{"opt":"$10$","error":"Usaste Pitágoras o cosenos cuando el par ángulo+opuesto pedía senos."}],"d":"dificil","theory":{"lesson_id":"filtro-L08","lesson_title":"Pitágoras, notables y senos","concept_title":"Pitágoras, notables y senos","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-226","n":226,"fam":"sines-pit","ch":"filtro-L08","t":"Pitágoras, notables y senos","topics":["filtro-pitagoras"],"prompt":"Ley de senos: si $A=30^{\\circ}$, $a=7$, $B=45^{\\circ}$, entonces $b$ vale:","opts":["$7\\sqrt{2}$","$\\dfrac{7}{\\sqrt{2}}$","$14$","$7\\sqrt{3}$"],"ans":0,"exp":"Paso 1: $\\dfrac{a}{\\operatorname{sen} A}=\\dfrac{b}{\\operatorname{sen} B}$. Paso 2: $\\dfrac{7}{\\operatorname{sen} 30^{\\circ}}=\\dfrac{b}{\\operatorname{sen} 45^{\\circ}}$. Paso 3: $\\operatorname{sen} 30^{\\circ}=\\dfrac{1}{2}$, $\\operatorname{sen} 45^{\\circ}=\\dfrac{\\sqrt{2}}{2}$, luego $b=7\\sqrt{2}$.","fig":null,"distractores":[{"opt":"$\\dfrac{7}{\\sqrt{2}}$","error":"Aplicaste la plantilla del notable equivocado ($30$ vs $45$)."},{"opt":"$14$","error":"Confundiste seno con coseno o con tangente."},{"opt":"$7\\sqrt{3}$","error":"Usaste Pitágoras o cosenos cuando el par ángulo+opuesto pedía senos."}],"d":"dificil","theory":{"lesson_id":"filtro-L08","lesson_title":"Pitágoras, notables y senos","concept_title":"Pitágoras, notables y senos","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-227","n":227,"fam":"sines-pit","ch":"filtro-L08","t":"Pitágoras, notables y senos","topics":["filtro-pitagoras"],"prompt":"Un triángulo rectángulo tiene catetos $5$ y $12$. El seno del ángulo opuesto al $5$ es:","opts":["$\\dfrac{12}{13}$","$\\dfrac{12}{5}$","$\\dfrac{5}{13}$","$\\dfrac{5}{12}$"],"ans":2,"exp":"Paso 1: hipotenusa $13$. Paso 2: $\\operatorname{sen}=\\dfrac{\\text{opuesto}}{\\text{hipotenusa}}=\\dfrac{5}{13}$. Paso 3: $\\dfrac{12}{13}$ es el coseno de ese ángulo (o el seno del otro).","fig":null,"distractores":[{"opt":"$\\dfrac{12}{13}$","error":"Aplicaste la plantilla del notable equivocado ($30$ vs $45$)."},{"opt":"$\\dfrac{12}{5}$","error":"Confundiste seno con coseno o con tangente."},{"opt":"$\\dfrac{5}{12}$","error":"Usaste Pitágoras o cosenos cuando el par ángulo+opuesto pedía senos."}],"d":"dificil","theory":{"lesson_id":"filtro-L08","lesson_title":"Pitágoras, notables y senos","concept_title":"Pitágoras, notables y senos","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-228","n":228,"fam":"sines-pit","ch":"filtro-L08","t":"Pitágoras, notables y senos","topics":["filtro-pitagoras"],"prompt":"Lados $4$, $6$, $11$:","opts":["no forman triángulo","rectángulo","obtusángulo","acutángulo"],"ans":0,"exp":"Paso 1: desigualdad triangular: $4+6=10<11$. Paso 2: no cierra. Paso 3: ni siquiera llegas a Pitágoras.","fig":null,"distractores":[{"opt":"rectángulo","error":"Aplicaste la plantilla del notable equivocado ($30$ vs $45$)."},{"opt":"obtusángulo","error":"Confundiste seno con coseno o con tangente."},{"opt":"acutángulo","error":"Usaste Pitágoras o cosenos cuando el par ángulo+opuesto pedía senos."}],"d":"dificil","theory":{"lesson_id":"filtro-L08","lesson_title":"Pitágoras, notables y senos","concept_title":"Pitágoras, notables y senos","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-229","n":229,"fam":"sines-pit","ch":"filtro-L08","t":"Pitágoras, notables y senos","topics":["filtro-pitagoras"],"prompt":"En $30^{\\circ}$-$60^{\\circ}$-$90^{\\circ}$, frente al $60^{\\circ}$ va:","opts":["$2a$","$a\\sqrt{2}$","$a$","$a\\sqrt{3}$ si el lado corto es $a$"],"ans":3,"exp":"Paso 1: corto (frente $30^{\\circ}$) $=a$, hipotenusa $=2a$, frente $60^{\\circ}$ $=a\\sqrt{3}$. Paso 2: no pongas $\\sqrt{3}$ frente al $30^{\\circ}$. Paso 3: $\\sqrt{2}$ es de $45$-$45$-$90$.","fig":null,"distractores":[{"opt":"$2a$","error":"Aplicaste la plantilla del notable equivocado ($30$ vs $45$)."},{"opt":"$a\\sqrt{2}$","error":"Confundiste seno con coseno o con tangente."},{"opt":"$a$","error":"Usaste Pitágoras o cosenos cuando el par ángulo+opuesto pedía senos."}],"d":"dificil","theory":{"lesson_id":"filtro-L08","lesson_title":"Pitágoras, notables y senos","concept_title":"Pitágoras, notables y senos","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-230","n":230,"fam":"sines-pit","ch":"filtro-L08","t":"Pitágoras, notables y senos","topics":["filtro-pitagoras"],"prompt":"Si conoces $a$, $A$ y $B$, para hallar $b$ usas:","opts":["solo Pitágoras","solo cosenos","Tales","ley de senos"],"ans":3,"exp":"Paso 1: ya tienes un par ángulo + lado opuesto ($a$ con $A$). Paso 2: $\\dfrac{a}{\\operatorname{sen} A}=\\dfrac{b}{\\operatorname{sen} B}$. Paso 3: cosenos pide dos lados y el ángulo incluido, o los tres lados.","fig":null,"distractores":[{"opt":"solo Pitágoras","error":"Aplicaste la plantilla del notable equivocado ($30$ vs $45$)."},{"opt":"solo cosenos","error":"Confundiste seno con coseno o con tangente."},{"opt":"Tales","error":"Usaste Pitágoras o cosenos cuando el par ángulo+opuesto pedía senos."}],"d":"dificil","theory":{"lesson_id":"filtro-L08","lesson_title":"Pitágoras, notables y senos","concept_title":"Pitágoras, notables y senos","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-231","n":231,"fam":"trig-id","ch":"filtro-L09","t":"Identidades y valores notables","topics":["filtro-ident"],"prompt":"Si $\\operatorname{sen}\\theta=\\dfrac{3}{2}$, entonces $\\cos\\theta$ (en reales) es:","opts":["$\\dfrac{\\sqrt{5}}{2}$","$0$","$\\pm\\dfrac{1}{2}$","imposible: no existe tal $\\theta$"],"ans":3,"exp":"Paso 1: $|\\operatorname{sen}\\theta|\\le 1$. Paso 2: $\\dfrac{3}{2}>1$. Paso 3: no hay coseno que inventar. La hoja que escribe $\\operatorname{sen}=3/2$ es una trampa, no un $3$-$4$-$5$.","fig":null,"distractores":[{"opt":"$\\dfrac{\\sqrt{5}}{2}$","error":"No pasaste todo a seno y coseno, o no cancelaste."},{"opt":"$0$","error":"Usaste el valor notable del ángulo espejo ($30$ por $60$)."},{"opt":"$\\pm\\dfrac{1}{2}$","error":"Inventaste un coseno para un seno imposible ($>1$)."}],"d":"dificil","theory":{"lesson_id":"filtro-L09","lesson_title":"Identidades y valores notables","concept_title":"Identidades y valores notables","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-232","n":232,"fam":"trig-id","ch":"filtro-L09","t":"Identidades y valores notables","topics":["filtro-ident"],"prompt":"Si $\\operatorname{sen}\\theta=\\dfrac{3}{5}$ y $\\theta$ es agudo, $\\cos\\theta$ vale:","opts":["$\\dfrac{5}{3}$","$-\\dfrac{4}{5}$","$\\dfrac{3}{4}$","$\\dfrac{4}{5}$"],"ans":3,"exp":"Paso 1: $\\operatorname{sen}^{2}+\\cos^{2}=1$ ⇒ $\\cos^{2}=1-\\dfrac{9}{25}=\\dfrac{16}{25}$. Paso 2: agudo ⇒ $\\cos>0$, $\\dfrac{4}{5}$. Paso 3: $-4/5$ sería el obtuso. $3/4$ es la tangente.","fig":null,"distractores":[{"opt":"$\\dfrac{5}{3}$","error":"No pasaste todo a seno y coseno, o no cancelaste."},{"opt":"$-\\dfrac{4}{5}$","error":"Usaste el valor notable del ángulo espejo ($30$ por $60$)."},{"opt":"$\\dfrac{3}{4}$","error":"Inventaste un coseno para un seno imposible ($>1$)."}],"d":"dificil","theory":{"lesson_id":"filtro-L09","lesson_title":"Identidades y valores notables","concept_title":"Identidades y valores notables","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-233","n":233,"fam":"trig-id","ch":"filtro-L09","t":"Identidades y valores notables","topics":["filtro-ident"],"prompt":"Si $\\operatorname{sen}\\theta=\\dfrac{5}{13}$ y $\\theta$ es obtuso, $\\cos\\theta$ vale:","opts":["$\\dfrac{12}{13}$","$\\dfrac{13}{5}$","$-\\dfrac{12}{13}$","$\\dfrac{5}{12}$"],"ans":2,"exp":"Paso 1: $\\cos^{2}=1-\\dfrac{25}{169}=\\dfrac{144}{169}$. Paso 2: obtuso ⇒ $\\cos<0$, $-\\dfrac{12}{13}$. Paso 3: el signo lo pone el cuadrante, no Pitágoras.","fig":null,"distractores":[{"opt":"$\\dfrac{12}{13}$","error":"No pasaste todo a seno y coseno, o no cancelaste."},{"opt":"$\\dfrac{13}{5}$","error":"Usaste el valor notable del ángulo espejo ($30$ por $60$)."},{"opt":"$\\dfrac{5}{12}$","error":"Inventaste un coseno para un seno imposible ($>1$)."}],"d":"dificil","theory":{"lesson_id":"filtro-L09","lesson_title":"Identidades y valores notables","concept_title":"Identidades y valores notables","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-234","n":234,"fam":"trig-id","ch":"filtro-L09","t":"Identidades y valores notables","topics":["filtro-ident"],"prompt":"Simplifique $\\cot^{2}\\theta\\cdot\\operatorname{sen}^{2}\\theta$ (donde existe):","opts":["$1$","$\\csc^{2}\\theta$","$\\operatorname{sen}^{2}\\theta$","$\\cos^{2}\\theta$"],"ans":3,"exp":"Paso 1: $\\cot=\\dfrac{\\cos}{\\operatorname{sen}}$. Paso 2: $\\dfrac{\\cos^{2}}{\\operatorname{sen}^{2}}\\cdot\\operatorname{sen}^{2}=\\cos^{2}$. Paso 3: se cancelan los senos (si $\\operatorname{sen}\\neq 0$).","fig":null,"distractores":[{"opt":"$1$","error":"No pasaste todo a seno y coseno, o no cancelaste."},{"opt":"$\\csc^{2}\\theta$","error":"Usaste el valor notable del ángulo espejo ($30$ por $60$)."},{"opt":"$\\operatorname{sen}^{2}\\theta$","error":"Inventaste un coseno para un seno imposible ($>1$)."}],"d":"dificil","theory":{"lesson_id":"filtro-L09","lesson_title":"Identidades y valores notables","concept_title":"Identidades y valores notables","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-235","n":235,"fam":"trig-id","ch":"filtro-L09","t":"Identidades y valores notables","topics":["filtro-ident"],"prompt":"Simplifique $\\tan\\theta\\cdot\\cos\\theta$ (donde existe):","opts":["$\\operatorname{sen}\\theta$","$\\tan\\theta$","$1$","$\\sec\\theta$"],"ans":0,"exp":"Paso 1: $\\tan=\\dfrac{\\operatorname{sen}}{\\cos}$. Paso 2: $\\dfrac{\\operatorname{sen}}{\\cos}\\cdot\\cos=\\operatorname{sen}$. Paso 3: el $\\cos$ se cancela si $\\cos\\neq 0$.","fig":null,"distractores":[{"opt":"$\\tan\\theta$","error":"No pasaste todo a seno y coseno, o no cancelaste."},{"opt":"$1$","error":"Usaste el valor notable del ángulo espejo ($30$ por $60$)."},{"opt":"$\\sec\\theta$","error":"Inventaste un coseno para un seno imposible ($>1$)."}],"d":"dificil","theory":{"lesson_id":"filtro-L09","lesson_title":"Identidades y valores notables","concept_title":"Identidades y valores notables","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-236","n":236,"fam":"trig-id","ch":"filtro-L09","t":"Identidades y valores notables","topics":["filtro-ident"],"prompt":"$\\cot^{2}\\theta\\cdot\\csc^{2}\\theta$ es equivalente a:","opts":["$1$","$\\operatorname{sen}^{2}\\theta\\cos^{2}\\theta$","$\\dfrac{\\operatorname{sen}^{2}\\theta}{\\cos^{2}\\theta}$","$\\dfrac{\\cos^{2}\\theta}{\\operatorname{sen}^{4}\\theta}$"],"ans":3,"exp":"Paso 1: $\\cot^{2}=\\dfrac{\\cos^{2}}{\\operatorname{sen}^{2}}$, $\\csc^{2}=\\dfrac{1}{\\operatorname{sen}^{2}}$. Paso 2: producto $\\dfrac{\\cos^{2}}{\\operatorname{sen}^{4}}$. Paso 3: no es $1$ (eso sería $\\operatorname{sen}\\cdot\\csc$).","fig":null,"distractores":[{"opt":"$1$","error":"No pasaste todo a seno y coseno, o no cancelaste."},{"opt":"$\\operatorname{sen}^{2}\\theta\\cos^{2}\\theta$","error":"Usaste el valor notable del ángulo espejo ($30$ por $60$)."},{"opt":"$\\dfrac{\\operatorname{sen}^{2}\\theta}{\\cos^{2}\\theta}$","error":"Inventaste un coseno para un seno imposible ($>1$)."}],"d":"dificil","theory":{"lesson_id":"filtro-L09","lesson_title":"Identidades y valores notables","concept_title":"Identidades y valores notables","anchor":"h-la-regla-solo-esto"}}));
