  ALL.push(Q({"id":"fp-251","n":251,"fam":"soh","ch":"filtro-L09","t":"SOH-CAH-TOA","topics":["filtro-razones"],"prompt":"En un triángulo rectángulo, el ángulo $\\theta$ mira al $8$ y la hipotenusa es $17$. $\\operatorname{sen}\\theta$ es:","opts":["$\\dfrac{15}{17}$","$\\dfrac{17}{8}$","$\\dfrac{8}{17}$","$\\dfrac{8}{15}$"],"ans":2,"exp":"Paso 1: $\\operatorname{sen}=\\dfrac{\\text{opuesto}}{\\text{hipotenusa}}$. Paso 2: $\\dfrac{8}{17}$. Paso 3: el otro cateto es $15$ (terna $8$-$15$-$17$): eso entra en cos o tan, no aquí.","fig":{"type":"filtro","name":"sohcahtoa"},"distractores":[{"opt":"$\\dfrac{15}{17}$","error":"Intercambiaste opuesto y adyacente."},{"opt":"$\\dfrac{17}{8}$","error":"Pusiste la hipotenusa en la tangente (o al revés)."},{"opt":"$\\dfrac{8}{15}$","error":"Usaste el recíproco equivocado (sec por csc)."}],"d":"dificil","theory":{"lesson_id":"filtro-L09","lesson_title":"SOH-CAH-TOA","concept_title":"SOH-CAH-TOA","anchor":"h-la-regla-solo-esto"}}));
