  ALL.push(Q({"id":"fp-255","n":255,"fam":"soh","ch":"filtro-L09","t":"SOH-CAH-TOA","topics":["filtro-razones"],"prompt":"En un triángulo rectángulo, un ángulo tiene adyacente $9$ e hipotenusa $15$. $\\operatorname{sen}$ de ese ángulo:","opts":["$\\dfrac{4}{5}$","$\\dfrac{3}{5}$","$\\dfrac{9}{15}$","$\\dfrac{12}{9}$"],"ans":0,"exp":"Paso 1: opuesto $=\\sqrt{15^{2}-9^{2}}=\\sqrt{225-81}=12$. Paso 2: $\\operatorname{sen}=\\dfrac{12}{15}=\\dfrac{4}{5}$. Paso 3: $\\dfrac{9}{15}=\\dfrac{3}{5}$ es el coseno.","fig":{"type":"filtro","name":"sohcahtoa"},"distractores":[{"opt":"$\\dfrac{3}{5}$","error":"Intercambiaste opuesto y adyacente."},{"opt":"$\\dfrac{9}{15}$","error":"Pusiste la hipotenusa en la tangente (o al revés)."},{"opt":"$\\dfrac{12}{9}$","error":"Usaste el recíproco equivocado (sec por csc)."}],"d":"dificil","theory":{"lesson_id":"filtro-L09","lesson_title":"SOH-CAH-TOA","concept_title":"SOH-CAH-TOA","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-256","n":256,"fam":"soh","ch":"filtro-L09","t":"SOH-CAH-TOA","topics":["filtro-razones"],"prompt":"SOH-CAH-TOA: $\\cos\\theta$ es:","opts":["$\\dfrac{\\text{adyacente}}{\\text{hipotenusa}}$","$\\dfrac{\\text{opuesto}}{\\text{adyacente}}$","$\\dfrac{\\text{hipotenusa}}{\\text{adyacente}}$","$\\dfrac{\\text{opuesto}}{\\text{hipotenusa}}$"],"ans":0,"exp":"Paso 1: CAH = Cos = Adyacente / Hipotenusa. Paso 2: seno usa el opuesto. Paso 3: tangente no usa hipotenusa.","fig":{"type":"filtro","name":"sohcahtoa"},"distractores":[{"opt":"$\\dfrac{\\text{opuesto}}{\\text{adyacente}}$","error":"Intercambiaste opuesto y adyacente."},{"opt":"$\\dfrac{\\text{hipotenusa}}{\\text{adyacente}}$","error":"Pusiste la hipotenusa en la tangente (o al revés)."},{"opt":"$\\dfrac{\\text{opuesto}}{\\text{hipotenusa}}$","error":"Usaste el recíproco equivocado (sec por csc)."}],"d":"dificil","theory":{"lesson_id":"filtro-L09","lesson_title":"SOH-CAH-TOA","concept_title":"SOH-CAH-TOA","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-257","n":257,"fam":"soh","ch":"filtro-L09","t":"SOH-CAH-TOA","topics":["filtro-razones"],"prompt":"Si $\\tan\\theta=\\dfrac{5}{12}$ (agudo), la hipotenusa en un triángulo reducido es:","opts":["$7$","$17$","$13$","$10$"],"ans":2,"exp":"Paso 1: opuesto $5$, adyacente $12$. Paso 2: $5^{2}+12^{2}=25+144=169=13^{2}$. Paso 3: $13$, no $17$ (esa es $8$-$15$-$17$).","fig":{"type":"filtro","name":"sohcahtoa"},"distractores":[{"opt":"$7$","error":"Intercambiaste opuesto y adyacente."},{"opt":"$17$","error":"Pusiste la hipotenusa en la tangente (o al revés)."},{"opt":"$10$","error":"Usaste el recíproco equivocado (sec por csc)."}],"d":"dificil","theory":{"lesson_id":"filtro-L09","lesson_title":"SOH-CAH-TOA","concept_title":"SOH-CAH-TOA","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-258","n":258,"fam":"soh","ch":"filtro-L09","t":"SOH-CAH-TOA","topics":["filtro-razones"],"prompt":"El recíproco de $\\operatorname{sen}\\theta$ es:","opts":["$\\sec\\theta$","$\\cos\\theta$","$\\cot\\theta$","$\\csc\\theta$"],"ans":3,"exp":"Paso 1: $\\csc=\\dfrac{1}{\\operatorname{sen}}$. Paso 2: $\\sec=1/\\cos$, $\\cot=1/\\tan$. Paso 3: no mezcles las parejas.","fig":{"type":"filtro","name":"sohcahtoa"},"distractores":[{"opt":"$\\sec\\theta$","error":"Intercambiaste opuesto y adyacente."},{"opt":"$\\cos\\theta$","error":"Pusiste la hipotenusa en la tangente (o al revés)."},{"opt":"$\\cot\\theta$","error":"Usaste el recíproco equivocado (sec por csc)."}],"d":"dificil","theory":{"lesson_id":"filtro-L09","lesson_title":"SOH-CAH-TOA","concept_title":"SOH-CAH-TOA","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-259","n":259,"fam":"soh","ch":"filtro-L09","t":"SOH-CAH-TOA","topics":["filtro-razones"],"prompt":"En un triángulo rectángulo, $\\theta$ y $90^{\\circ}-\\theta$ cumplen:","opts":["$\\operatorname{sen}\\theta=\\cos(90^{\\circ}-\\theta)$","$\\tan\\theta=\\tan(90^{\\circ}-\\theta)$","$\\operatorname{sen}\\theta=\\operatorname{sen}(90^{\\circ}-\\theta)$","$\\cos\\theta=\\cos(90^{\\circ}-\\theta)$"],"ans":0,"exp":"Paso 1: el opuesto de uno es el adyacente del complemento. Paso 2: $\\operatorname{sen}\\theta=\\cos(90^{\\circ}-\\theta)$. Paso 3: las tangentes son recíprocas, no iguales.","fig":{"type":"filtro","name":"sohcahtoa"},"distractores":[{"opt":"$\\tan\\theta=\\tan(90^{\\circ}-\\theta)$","error":"Intercambiaste opuesto y adyacente."},{"opt":"$\\operatorname{sen}\\theta=\\operatorname{sen}(90^{\\circ}-\\theta)$","error":"Pusiste la hipotenusa en la tangente (o al revés)."},{"opt":"$\\cos\\theta=\\cos(90^{\\circ}-\\theta)$","error":"Usaste el recíproco equivocado (sec por csc)."}],"d":"dificil","theory":{"lesson_id":"filtro-L09","lesson_title":"SOH-CAH-TOA","concept_title":"SOH-CAH-TOA","anchor":"h-la-regla-solo-esto"}}));
