  ALL.push(Q({"id":"fp-261","n":261,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"La ecuación de la circunferencia de centro $(3,-2)$ y radio $5$ es:","opts":["$(x-3)^{2}+(y+2)^{2}=25$","$(x+3)^{2}+(y-2)^{2}=25$","$(x-3)^{2}+(y+2)^{2}=5$","$x^{2}+y^{2}=25$"],"ans":0,"exp":"Paso 1: canónica $(x-h)^{2}+(y-k)^{2}=r^{2}$ con $h=3$, $k=-2$. Paso 2: $(x-3)^{2}$ se escribe $(x-3)^{2}$; análogo en $y$. Paso 3: a la derecha va $r^{2}=25$, no $r$.","fig":{"type":"filtro","name":"circle-canon"},"distractores":[{"opt":"$(x+3)^{2}+(y-2)^{2}=25$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"$(x-3)^{2}+(y+2)^{2}=5$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"$x^{2}+y^{2}=25$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
