  ALL.push(Q({"id":"fp-268","n":268,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"La ecuación de la circunferencia de centro $(1,-7)$ y radio $\\sqrt{13}$ es:","opts":["$x^{2}+y^{2}=13$","$(x-1)^{2}+(y+7)^{2}=13$","$(x+1)^{2}+(y-7)^{2}=13$","$(x-1)^{2}+(y+7)^{2}=4$"],"ans":1,"exp":"Paso 1: canónica $(x-h)^{2}+(y-k)^{2}=r^{2}$ con $h=1$, $k=-7$. Paso 2: $(x-1)^{2}$ se escribe $(x-1)^{2}$; análogo en $y$. Paso 3: a la derecha va $r^{2}=13$, no $r$.","fig":{"type":"filtro","name":"circle-canon"},"distractores":[{"opt":"$x^{2}+y^{2}=13$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"$(x+1)^{2}+(y-7)^{2}=13$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"$(x-1)^{2}+(y+7)^{2}=4$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-269","n":269,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"Al pasar $x^{2}+y^{2}-6x+4y-12=0$ a canónica, el centro es:","opts":["$(-6,4)$","$(-3,2)$","$(3,-2)$","$(3,2)$"],"ans":2,"exp":"Paso 1: centro $\\left(-\\dfrac{D}{2},-\\dfrac{E}{2}\\right)=\\left(-\\dfrac{-6}{2},-\\dfrac{4}{2}\\right)=(3,-2)$. Paso 2: completar cuadrados da lo mismo. Paso 3: no uses $(D,E)$ ni olvides los menos.","fig":{"type":"filtro","name":"circle-general"},"distractores":[{"opt":"$(-6,4)$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"$(-3,2)$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"$(3,2)$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-270","n":270,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"El radio de $x^{2}+y^{2}+8x-2y-8=0$ es:","opts":["$5$","$\\sqrt{8}$","$8$","$4$"],"ans":0,"exp":"Paso 1: $r^{2}=\\left(\\dfrac{D}{2}\\right)^{2}+\\left(\\dfrac{E}{2}\\right)^{2}-F=16+1-(-8)=25$. Paso 2: $r=5$. Paso 3: el radio no es $|h|$ ni $|F|$.","fig":{"type":"filtro","name":"circle-canon"},"distractores":[{"opt":"$\\sqrt{8}$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"$8$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"$4$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-271","n":271,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"Al pasar $x^{2}+y^{2}-4x+6y-3=0$ a canónica, el centro es:","opts":["$(2,-3)$","$(-4,6)$","$(2,3)$","$(-2,3)$"],"ans":0,"exp":"Paso 1: centro $\\left(-\\dfrac{D}{2},-\\dfrac{E}{2}\\right)=\\left(-\\dfrac{-4}{2},-\\dfrac{6}{2}\\right)=(2,-3)$. Paso 2: completar cuadrados da lo mismo. Paso 3: no uses $(D,E)$ ni olvides los menos.","fig":{"type":"filtro","name":"circle-general"},"distractores":[{"opt":"$(-4,6)$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"$(2,3)$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"$(-2,3)$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-272","n":272,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"El radio de $x^{2}+y^{2}+2x+8y-8=0$ es:","opts":["$8$","$1$","$5$","$\\sqrt{8}$"],"ans":2,"exp":"Paso 1: $r^{2}=\\left(\\dfrac{D}{2}\\right)^{2}+\\left(\\dfrac{E}{2}\\right)^{2}-F=1+16-(-8)=25$. Paso 2: $r=5$. Paso 3: el radio no es $|h|$ ni $|F|$.","fig":{"type":"filtro","name":"circle-canon"},"distractores":[{"opt":"$8$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"$1$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"$\\sqrt{8}$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-273","n":273,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"Al pasar $x^{2}+y^{2}-10x-4y+13=0$ a canónica, el centro es:","opts":["$(-5,-2)$","$(5,-2)$","$(-10,-4)$","$(5,2)$"],"ans":3,"exp":"Paso 1: centro $\\left(-\\dfrac{D}{2},-\\dfrac{E}{2}\\right)=\\left(-\\dfrac{-10}{2},-\\dfrac{-4}{2}\\right)=(5,2)$. Paso 2: completar cuadrados da lo mismo. Paso 3: no uses $(D,E)$ ni olvides los menos.","fig":{"type":"filtro","name":"circle-general"},"distractores":[{"opt":"$(-5,-2)$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"$(5,-2)$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"$(-10,-4)$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-274","n":274,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"El radio de $x^{2}+y^{2}+6x-10y+18=0$ es:","opts":["$4$","$18$","$\\sqrt{18}$","$3$"],"ans":0,"exp":"Paso 1: $r^{2}=\\left(\\dfrac{D}{2}\\right)^{2}+\\left(\\dfrac{E}{2}\\right)^{2}-F=9+25-(18)=16$. Paso 2: $r=4$. Paso 3: el radio no es $|h|$ ni $|F|$.","fig":{"type":"filtro","name":"circle-canon"},"distractores":[{"opt":"$18$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"$\\sqrt{18}$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"$3$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-275","n":275,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"Al pasar $x^{2}+y^{2}-8x-9=0$ a canónica, el centro es:","opts":["$(-4,0)$","$2$","$(4,0)$","$(-8,0)$"],"ans":2,"exp":"Paso 1: centro $\\left(-\\dfrac{D}{2},-\\dfrac{E}{2}\\right)=\\left(-\\dfrac{-8}{2},-\\dfrac{0}{2}\\right)=(4,0)$. Paso 2: completar cuadrados da lo mismo. Paso 3: no uses $(D,E)$ ni olvides los menos.","fig":{"type":"filtro","name":"circle-general"},"distractores":[{"opt":"$(-4,0)$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"$2$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"$(-8,0)$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-276","n":276,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"El radio de $x^{2}+y^{2}+12y-4=0$ es:","opts":["$\\sqrt{40}$","$0$","$4$","$\\sqrt{4}$"],"ans":0,"exp":"Paso 1: $r^{2}=\\left(\\dfrac{D}{2}\\right)^{2}+\\left(\\dfrac{E}{2}\\right)^{2}-F=0+36-(-4)=40$. Paso 2: $r=\\sqrt{40}$. Paso 3: el radio no es $|h|$ ni $|F|$.","fig":{"type":"filtro","name":"circle-canon"},"distractores":[{"opt":"$0$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"$4$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"$\\sqrt{4}$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-277","n":277,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"Los extremos de un diámetro son $A(-2,1)$ y $B(4,5)$. La ecuación de la circunferencia es:","opts":["$(x-1)^{2}+(y-3)^{2}=13$","$(x-1)^{2}+(y-3)^{2}=\\sqrt{13}$","$(x+1)^{2}+(y-3)^{2}=13$","$(x-4)^{2}+(y-5)^{2}=13$"],"ans":0,"exp":"Paso 1: centro = punto medio $\\left(\\dfrac{-2+4}{2},\\dfrac{1+5}{2}\\right)=(1,3)$. Paso 2: $r^{2}=(4-1)^{2}+(5-3)^{2}=9+4=13$. Paso 3: $(x-1)^{2}+(y-3)^{2}=13$. A la derecha va $r^{2}$, no $r$.","fig":{"type":"filtro","name":"circle-canon"},"distractores":[{"opt":"$(x-1)^{2}+(y-3)^{2}=\\sqrt{13}$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"$(x+1)^{2}+(y-3)^{2}=13$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"$(x-4)^{2}+(y-5)^{2}=13$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-278","n":278,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"Diámetro de $A(0,-4)$ a $B(6,2)$. El centro es:","opts":["$(6,-4)$","$(3,3)$","$(0,2)$","$(3,-1)$"],"ans":3,"exp":"Paso 1: medio $\\left(\\dfrac{0+6}{2},\\dfrac{-4+2}{2}\\right)=(3,-1)$. Paso 2: no uses un extremo como centro. Paso 3: $r^{2}=(6-3)^{2}+(2+1)^{2}=9+9=18$.","fig":{"type":"filtro","name":"circle-canon"},"distractores":[{"opt":"$(6,-4)$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"$(3,3)$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"$(0,2)$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-279","n":279,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"¿El punto $(1,2)$ está en $(x-1)^{2}+(y+3)^{2}=25$?","opts":["no, porque $1+2\\neq 25$","sí, porque $0^{2}+5^{2}=25$","no, el radio es $5$ y el punto está a $3$","sí, porque el centro es $(1,2)$"],"ans":1,"exp":"Paso 1: sustituye $x=1$, $y=2$: $(0)^{2}+(5)^{2}=25$. Paso 2: cumple. Paso 3: el centro es $(1,-3)$, no $(1,2)$. La distancia es $5$, igual al radio.","fig":{"type":"filtro","name":"circle-canon"},"distractores":[{"opt":"no, porque $1+2\\neq 25$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"no, el radio es $5$ y el punto está a $3$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"sí, porque el centro es $(1,2)$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-280","n":280,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"Circunferencia de centro $(2,5)$ tangente al eje $X$. Su radio es:","opts":["$5$","$\\sqrt{29}$","$2$","$7$"],"ans":0,"exp":"Paso 1: tangente al eje $X$ ⇒ la distancia vertical al eje es el radio. Paso 2: $|k|=|5|=5$. Paso 3: no uses $|h|=2$ (eso sería tangente al eje $Y$).","fig":{"type":"filtro","name":"circle-canon"},"distractores":[{"opt":"$\\sqrt{29}$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"$2$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"$7$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-281","n":281,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"Circunferencia de centro $(4,-1)$ tangente al eje $Y$. Una ecuación posible es:","opts":["$(x+4)^{2}+(y-1)^{2}=16$","$(x-4)^{2}+(y+1)^{2}=1$","$(x-4)^{2}+(y+1)^{2}=16$","$(x-4)^{2}+(y+1)^{2}=4$"],"ans":2,"exp":"Paso 1: tangente al eje $Y$ ⇒ $r=|h|=4$, $r^{2}=16$. Paso 2: centro $(4,-1)$ ⇒ $(x-4)^{2}+(y+1)^{2}=16$. Paso 3: $r=1$ sería $|k|$.","fig":{"type":"filtro","name":"circle-canon"},"distractores":[{"opt":"$(x+4)^{2}+(y-1)^{2}=16$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"$(x-4)^{2}+(y+1)^{2}=1$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"$(x-4)^{2}+(y+1)^{2}=4$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-282","n":282,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"En el primer cuadrante, tangente a ambos ejes y radio $3$. Su ecuación es:","opts":["$(x-3)^{2}+(y-3)^{2}=9$","$x^{2}+y^{2}=9$","$(x-3)^{2}+(y-3)^{2}=3$","$(x+3)^{2}+(y+3)^{2}=9$"],"ans":0,"exp":"Paso 1: tangente a ambos ejes en el primer cuadrante ⇒ centro $(r,r)=(3,3)$. Paso 2: $r^{2}=9$. Paso 3: $(x+3)^{2}+(y+3)^{2}$ vive en el tercer cuadrante.","fig":{"type":"filtro","name":"circle-canon"},"distractores":[{"opt":"$x^{2}+y^{2}=9$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"$(x-3)^{2}+(y-3)^{2}=3$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"$(x+3)^{2}+(y+3)^{2}=9$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-283","n":283,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"Centro $(2,-1)$ y tangente a la recta $x+y-5=0$. El radio es:","opts":["$6$","$2\\sqrt{2}$","$4$","$\\dfrac{4}{\\sqrt{2}}$ visto como $2$"],"ans":1,"exp":"Paso 1: distancia centro-recta $d=\\dfrac{|2+(-1)-5|}{\\sqrt{1^{2}+1^{2}}}=\\dfrac{4}{\\sqrt{2}}=2\\sqrt{2}$. Paso 2: tangente ⇒ $r=d$. Paso 3: no dejes $\\dfrac{4}{\\sqrt{2}}$ sin simplificar, y no uses $|2-1-5|$ con otro denominador.","fig":{"type":"filtro","name":"circle-canon"},"distractores":[{"opt":"$6$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"$4$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"$\\dfrac{4}{\\sqrt{2}}$ visto como $2$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-284","n":284,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"Centro $(-3,4)$ y tangente a $3x-4y+8=0$. El radio es:","opts":["$5$","$11$","$\\dfrac{17}{5}$","$\\dfrac{7}{5}$"],"ans":2,"exp":"Paso 1: $d=\\dfrac{|3(-3)-4(4)+8|}{\\sqrt{9+16}}=\\dfrac{|-9-16+8|}{5}=\\dfrac{17}{5}$. Paso 2: tangente ⇒ $r=d=\\dfrac{17}{5}$. Paso 3: el $5$ es $\\sqrt{3^{2}+4^{2}}$, no se tira.","fig":{"type":"filtro","name":"circle-canon"},"distractores":[{"opt":"$5$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"$11$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"$\\dfrac{7}{5}$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-285","n":285,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"La circunferencia $x^{2}+y^{2}-4x+2y-20=0$ y la recta $x=3$: ¿cuántos puntos en común?","opts":["dos (cuerda)","uno (tangente)","ninguno","infinitos"],"ans":0,"exp":"Paso 1: centro $(2,-1)$, $r^{2}=4+1+20=25$, $r=5$. Paso 2: distancia del centro a $x=3$ es $|3-2|=1<5$. Paso 3: $d<r$ ⇒ dos cortes.","fig":{"type":"filtro","name":"circle-canon"},"distractores":[{"opt":"uno (tangente)","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"ninguno","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"infinitos","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-286","n":286,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"Misma circunferencia (centro $(2,-1)$, $r=5$) y la recta $y=4$. Puntos en común:","opts":["el centro","uno (tangente)","dos","ninguno"],"ans":1,"exp":"Paso 1: distancia de $(2,-1)$ a $y=4$ es $|4-(-1)|=5$. Paso 2: $d=r$ ⇒ tangente, un punto. Paso 3: el punto es $(2,4)$.","fig":{"type":"filtro","name":"circle-canon"},"distractores":[{"opt":"el centro","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"dos","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"ninguno","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-287","n":287,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"Una circunferencia pasa por el origen y tiene centro $(3,4)$. Su ecuación es:","opts":["$x^{2}+y^{2}=25$","$(x+3)^{2}+(y+4)^{2}=25$","$(x-3)^{2}+(y-4)^{2}=25$","$(x-3)^{2}+(y-4)^{2}=7$"],"ans":2,"exp":"Paso 1: el radio es la distancia del centro al origen: $\\sqrt{9+16}=5$, $r^{2}=25$. Paso 2: $(x-3)^{2}+(y-4)^{2}=25$. Paso 3: $x^{2}+y^{2}=25$ estaría centrada en el origen.","fig":{"type":"filtro","name":"circle-canon"},"distractores":[{"opt":"$x^{2}+y^{2}=25$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"$(x+3)^{2}+(y+4)^{2}=25$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"$(x-3)^{2}+(y-4)^{2}=7$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-288","n":288,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"De $x^{2}+y^{2}+Dx+Ey+F=0$, $r^{2}$ vale:","opts":["$\\left(\\dfrac{D}{2}\\right)^{2}+\\left(\\dfrac{E}{2}\\right)^{2}-F$","$D^{2}+E^{2}-F$","$F$","$-F$"],"ans":0,"exp":"Paso 1: completar cuadrados. Paso 2: $r^{2}=(D/2)^{2}+(E/2)^{2}-F$. Paso 3: si eso sale negativo, no es circunferencia real.","fig":{"type":"filtro","name":"circle-canon"},"distractores":[{"opt":"$D^{2}+E^{2}-F$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"$F$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"$-F$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-289","n":289,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"$x^{2}+y^{2}+2x+2y+3=0$ representa:","opts":["la recta $x+y+3=0$","ningún punto real ($r^{2}<0$)","circunferencia de radio $1$","el punto $(-1,-1)$"],"ans":1,"exp":"Paso 1: $(x+1)^{2}+(y+1)^{2}+3-1-1=0$ ⇒ $(x+1)^{2}+(y+1)^{2}=-1$. Paso 2: $r^{2}=-1<0$. Paso 3: conjunto vacío en el plano real.","fig":{"type":"filtro","name":"circle-canon"},"distractores":[{"opt":"la recta $x+y+3=0$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"circunferencia de radio $1$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"el punto $(-1,-1)$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-290","n":290,"fam":"circle","ch":"filtro-L10","t":"Circunferencia","topics":["filtro-circ"],"prompt":"Centro en el eje $X$, radio $5$, pasa por $(0,4)$. Una ecuación posible es:","opts":["$x^{2}+(y-3)^{2}=25$","$(x-5)^{2}+y^{2}=16$","$(x-4)^{2}+y^{2}=25$","$(x-3)^{2}+y^{2}=25$"],"ans":3,"exp":"Paso 1: centro $(h,0)$, $r=5$, pasa por $(0,4)$: $(0-h)^{2}+16=25$. Paso 2: $h^{2}=9$, $h=\\pm 3$. Paso 3: $(x-3)^{2}+y^{2}=25$ (o $(x+3)^{2}+y^{2}=25$). $(x-4)$ no cumple $h^{2}=9$.","fig":{"type":"filtro","name":"circle-canon"},"distractores":[{"opt":"$x^{2}+(y-3)^{2}=25$","error":"Cambiaste el signo del centro $(x+h)$ en vez de $(x-h)$."},{"opt":"$(x-5)^{2}+y^{2}=16$","error":"Pusiste $r$ a la derecha en vez de $r^{2}$, o usaste $|h|$ por $|k|$."},{"opt":"$(x-4)^{2}+y^{2}=25$","error":"No completaste el cuadrado / no usaste $r^{2}=(D/2)^{2}+(E/2)^{2}-F$."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Circunferencia","concept_title":"Circunferencia","anchor":"h-la-regla-solo-esto"}}));
  ALL.push(Q({"id":"fp-291","n":291,"fam":"slope","ch":"filtro-L10","t":"Pendiente","topics":["filtro-pendiente"],"prompt":"La pendiente entre $(0,0)$ y $(2,-4)$ es:","opts":["$-2$","$0$","$2$","$-\\dfrac{1}{2}$"],"ans":0,"exp":"Paso 1: $m=\\dfrac{y_{2}-y_{1}}{x_{2}-x_{1}}=\\dfrac{-4-0}{2-0}=\\dfrac{-4}{2}=-2$. Paso 2: el mismo orden arriba y abajo. Paso 3: baja: signo menos.","fig":{"type":"filtro","name":"slope"},"distractores":[{"opt":"$0$","error":"Invertiste $\\Delta y$ y $\\Delta x$."},{"opt":"$2$","error":"Cambiaste el orden solo en un coordenada (sale el signo al revés)."},{"opt":"$-\\dfrac{1}{2}$","error":"Marcaste $0$ como si fuera horizontal."}],"d":"dificil","theory":{"lesson_id":"filtro-L10","lesson_title":"Pendiente","concept_title":"Pendiente","anchor":"h-la-regla-solo-esto"}}));
